INSERT INTO sat_questions
  (id, skill_id, stem, explanation, answer_type, options, correct_index,
   accepted_answers, difficulty, irt_a, irt_b, irt_c, is_diagnostic, source)
VALUES
  ('arith-0021', 'arithmetic-percentages', 'What is \(25\%\) of \(80\)?', '\(25\% = \tfrac14\), and \(\tfrac14 \times 80 = 20\).', 'mc', '["\\(20\\)","\\(40\\)","\\(16\\)","\\(55\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0022', 'arithmetic-percentages', 'What is \(15\%\) of \(60\)?', '\(15\% = 0.15\), and \(0.15 \times 60 = 9\).', 'mc', '["\\(15\\)","\\(9\\)","\\(45\\)","\\(4\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0023', 'arithmetic-percentages', 'A shirt that costs \(40\) dollars is marked down by \(20\%\). What is the discount, in dollars?', 'The discount is \(20\%\) of \(40\): \(0.20 \times 40 = 8\) dollars.', 'mc', '["\\(20\\)","\\(32\\)","\\(8\\)","\\(4\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0024', 'arithmetic-percentages', '\(12\) is what percent of \(48\)?', '\(\tfrac{12}{48} = 0.25 = 25\%\).', 'mc', '["\\(4\\%\\)","\\(36\\%\\)","\\(40\\%\\)","\\(25\\%\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0025', 'arithmetic-percentages', 'Write \(\tfrac{3}{5}\) as a percent.', '\(\tfrac{3}{5} = 0.6 = 60\%\).', 'mc', '["\\(60\\%\\)","\\(35\\%\\)","\\(53\\%\\)","\\(30\\%\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0026', 'arithmetic-percentages', 'A car travels \(150\) miles in \(3\) hours. What is its average speed, in miles per hour?', 'Average speed is distance divided by time: \(150 \div 3 = 50\) miles per hour.', 'mc', '["\\(450\\)","\\(50\\)","\\(147\\)","\\(75\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0027', 'arithmetic-percentages', 'A recipe uses flour and sugar in the ratio \(3:1\). If \(6\) cups of flour are used, how many cups of sugar are needed?', 'The ratio \(3:1\) means sugar is one third of the flour: \(6 \div 3 = 2\) cups.', 'mc', '["\\(18\\)","\\(3\\)","\\(2\\)","\\(6\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0028', 'arithmetic-percentages', 'What number is \(30\%\) of \(200\)?', '\(0.30 \times 200 = 60\).', 'mc', '["\\(6\\)","\\(600\\)","\\(170\\)","\\(60\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0029', 'arithmetic-percentages', 'A price of \(50\) dollars increases by \(10\%\). What is the new price, in dollars?', 'The increase is \(0.10 \times 50 = 5\) dollars, so the new price is \(50 + 5 = 55\) dollars.', 'mc', '["\\(55\\)","\\(60\\)","\\(45\\)","\\(51\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0030', 'arithmetic-percentages', '\(40\%\) of a number is \(20\). What is the number?', 'If \(0.40 x = 20\), then \(x = 20 \div 0.40 = 50\).', 'mc', '["\\(8\\)","\\(50\\)","\\(60\\)","\\(80\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0031', 'arithmetic-percentages', 'Convert \(0.045\) to a percent.', 'Multiply by \(100\): \(0.045 \times 100 = 4.5\%\).', 'mc', '["\\(45\\%\\)","\\(0.45\\%\\)","\\(4.5\\%\\)","\\(450\\%\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0032', 'arithmetic-percentages', 'A store adds \(8\%\) sales tax to a \(25\) dollar purchase. What is the tax, in dollars?', 'The tax is \(8\%\) of \(25\): \(0.08 \times 25 = 2\) dollars.', 'mc', '["\\(8\\)","\\(20\\)","\\(2.5\\)","\\(2\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0033', 'arithmetic-percentages', 'The ratio of boys to girls in a class is \(2:3\). If there are \(10\) boys, how many girls are there?', 'Each ratio unit is \(10 \div 2 = 5\) students, so girls \(= 3 \times 5 = 15\).', 'mc', '["\\(15\\)","\\(6\\)","\\(20\\)","\\(5\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0034', 'arithmetic-percentages', 'What is the average of \(12\), \(18\), and \(24\)?', 'The mean is \(\tfrac{12 + 18 + 24}{3} = \tfrac{54}{3} = 18\).', 'mc', '["\\(54\\)","\\(18\\)","\\(15\\)","\\(20\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0035', 'arithmetic-percentages', 'A \(20\) dollar tip is what percent of a \(80\) dollar bill?', '\(\tfrac{20}{80} = 0.25 = 25\%\).', 'mc', '["\\(20\\%\\)","\\(40\\%\\)","\\(25\\%\\)","\\(16\\%\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0036', 'arithmetic-percentages', 'If \(3\) notebooks cost \(6\) dollars, what is the cost of \(5\) notebooks, in dollars?', 'Each notebook costs \(6 \div 3 = 2\) dollars, so \(5\) cost \(5 \times 2 = 10\) dollars.', 'mc', '["\\(11\\)","\\(30\\)","\\(2\\)","\\(10\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0037', 'arithmetic-percentages', 'A number increased from \(20\) to \(25\). What is the percent increase?', 'The increase is \(5\); as a percent of the original \(20\), \(\tfrac{5}{20} = 25\%\).', 'mc', '["\\(25\\%\\)","\\(5\\%\\)","\\(20\\%\\)","\\(80\\%\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0038', 'arithmetic-percentages', 'Solve the proportion \(\dfrac{x}{12} = \dfrac{3}{4}\).', 'Cross-multiply: \(4x = 36\), so \(x = 9\).', 'mc', '["\\(16\\)","\\(9\\)","\\(4\\)","\\(36\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0039', 'arithmetic-percentages', 'After a \(20\%\) discount, a jacket costs \(48\) dollars. What was the original price, in dollars?', 'The sale price is \(80\%\) of the original: \(0.80 x = 48\), so \(x = 48 \div 0.80 = 60\) dollars.', 'mc', '["\\(60\\)","\\(57.6\\)","\\(68\\)","\\(40\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0040', 'arithmetic-percentages', 'A price is increased by \(25\%\) and then decreased by \(20\%\). The final price is what percent of the original?', 'Multiply the factors: \(1.25 \times 0.80 = 1.00\), so the price returns to \(100\%\).', 'mc', '["\\(105\\%\\)","\\(100\\%\\)","\\(95\\%\\)","\\(45\\%\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0041', 'arithmetic-percentages', 'On a test, a student answered \(42\) of \(50\) questions correctly. What percent were incorrect?', 'Incorrect \(= 50 - 42 = 8\); \(\tfrac{8}{50} = 0.16 = 16\%\).', 'mc', '["\\(84\\%\\)","\\(8\\%\\)","\\(16\\%\\)","\\(42\\%\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0042', 'arithmetic-percentages', 'A solution is \(30\%\) acid. How many liters of acid are in \(40\) liters of solution?', '\(30\%\) of \(40\) is \(0.30 \times 40 = 12\) liters.', 'mc', '["\\(30\\)","\\(1.2\\)","\\(28\\)","\\(12\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0043', 'arithmetic-percentages', 'The population of a town grew from \(2{,}500\) to \(2{,}900\). What is the percent increase?', 'The increase is \(400\); \(\tfrac{400}{2500} = 0.16 = 16\%\).', 'mc', '["\\(16\\%\\)","\\(14\\%\\)","\\(40\\%\\)","\\(13.8\\%\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0044', 'arithmetic-percentages', 'A car uses \(4\) gallons of gas to travel \(96\) miles. At this rate, how many gallons are needed for \(240\) miles?', 'The rate is \(96 \div 4 = 24\) miles per gallon, so \(240 \div 24 = 10\) gallons.', 'mc', '["\\(60\\)","\\(10\\)","\\(9.6\\)","\\(8\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0045', 'arithmetic-percentages', 'A class has \(12\) boys and \(18\) girls. What percent of the class is boys?', 'Total is \(30\); \(\tfrac{12}{30} = 0.40 = 40\%\).', 'mc', '["\\(60\\%\\)","\\(12\\%\\)","\\(40\\%\\)","\\(66.7\\%\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0046', 'arithmetic-percentages', 'An item costing \(200\) dollars is marked up \(15\%\), then a \(10\) dollar coupon is applied. What is the final price, in dollars?', 'After markup: \(200 \times 1.15 = 230\); minus the coupon: \(230 - 10 = 220\) dollars.', 'mc', '["\\(230\\)","\\(205\\)","\\(219\\)","\\(220\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0047', 'arithmetic-percentages', 'The ratio of red to blue marbles is \(5:3\). If there are \(64\) marbles in all, how many are blue?', 'There are \(5 + 3 = 8\) parts, so each part is \(64 \div 8 = 8\) marbles; blue \(= 3 \times 8 = 24\).', 'mc', '["\\(24\\)","\\(40\\)","\\(8\\)","\\(21\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0048', 'arithmetic-percentages', 'A worker''s hourly wage rises from \(16\) to \(20\) dollars. What is the percent increase?', 'The increase is \(4\); \(\tfrac{4}{16} = 0.25 = 25\%\).', 'mc', '["\\(20\\%\\)","\\(25\\%\\)","\\(4\\%\\)","\\(80\\%\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0049', 'arithmetic-percentages', 'A \(300\) dollar deposit earns \(6\%\) simple interest per year. How much interest is earned after \(2\) years, in dollars?', 'Simple interest is \(P r t = 300 \times 0.06 \times 2 = 36\) dollars.', 'mc', '["\\(18\\)","\\(72\\)","\\(36\\)","\\(318\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0050', 'arithmetic-percentages', 'Two numbers are in the ratio \(4:7\), and the larger is \(63\). What is the smaller number?', 'Each unit is \(63 \div 7 = 9\), so the smaller is \(4 \times 9 = 36\).', 'mc', '["\\(9\\)","\\(28\\)","\\(45\\)","\\(36\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0051', 'arithmetic-percentages', 'A shirt normally \(50\) dollars is on sale for \(35\) dollars. What is the percent discount?', 'The discount is \(15\); \(\tfrac{15}{50} = 0.30 = 30\%\).', 'mc', '["\\(30\\%\\)","\\(15\\%\\)","\\(70\\%\\)","\\(43\\%\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0052', 'arithmetic-percentages', 'A recipe for \(4\) servings needs \(3\) cups of rice. How many cups are needed for \(10\) servings?', 'The rate is \(\tfrac34\) cup per serving, so \(10 \times \tfrac34 = 7.5\) cups.', 'mc', '["\\(30\\)","\\(7.5\\)","\\(1.2\\)","\\(12\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0053', 'arithmetic-percentages', 'A bag holds \(60\) candies: \(45\%\) are red. How many are not red?', 'Red \(= 0.45 \times 60 = 27\), so not red \(= 60 - 27 = 33\).', 'mc', '["\\(27\\)","\\(15\\)","\\(33\\)","\\(45\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0054', 'arithmetic-percentages', 'A number is \(150\%\) of \(48\). What is the number?', '\(150\% = 1.5\), and \(1.5 \times 48 = 72\).', 'mc', '["\\(24\\)","\\(96\\)","\\(63\\)","\\(72\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0055', 'arithmetic-percentages', 'A store buys an item for \(80\) dollars and sells it for \(100\) dollars. What is the percent profit based on cost?', 'Profit is \(20\); as a percent of the \(80\) cost, \(\tfrac{20}{80} = 25\%\).', 'mc', '["\\(25\\%\\)","\\(20\\%\\)","\\(80\\%\\)","\\(125\\%\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0056', 'arithmetic-percentages', 'A measurement was recorded as \(52\) but the true value is \(50\). What is the percent error?', 'Percent error is \(\tfrac{|52 - 50|}{50} = \tfrac{2}{50} = 4\%\).', 'mc', '["\\(2\\%\\)","\\(4\\%\\)","\\(3.8\\%\\)","\\(52\\%\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0057', 'arithmetic-percentages', 'A cyclist rides \(30\) miles at \(15\) miles per hour, then \(30\) miles at \(10\) miles per hour. What is the average speed for the whole trip, in miles per hour?', 'Total time is \(\tfrac{30}{15} + \tfrac{30}{10} = 2 + 3 = 5\) hours for \(60\) miles: \(60 \div 5 = 12\) miles per hour.', 'mc', '["\\(12.5\\)","\\(25\\)","\\(12\\)","\\(5\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0058', 'arithmetic-percentages', 'In a survey, \(35\%\) of \(240\) people chose option A. How many people chose option A?', '\(0.35 \times 240 = 84\) people.', 'mc', '["\\(68.6\\)","\\(156\\)","\\(35\\)","\\(84\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0059', 'arithmetic-percentages', 'A quantity increases by \(40\%\) to become \(70\). What was the original quantity?', 'If \(1.40 x = 70\), then \(x = 70 \div 1.40 = 50\).', 'mc', '["\\(50\\)","\\(42\\)","\\(30\\)","\\(98\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0060', 'arithmetic-percentages', 'A map uses a scale of \(1\) inch to \(25\) miles. Two cities are \(3.5\) inches apart on the map. How many miles apart are they?', 'Distance is \(3.5 \times 25 = 87.5\) miles.', 'mc', '["\\(7.14\\)","\\(87.5\\)","\\(28.5\\)","\\(75\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0061', 'arithmetic-percentages', 'A phone''s price dropped \(10\%\) in March and another \(10\%\) in April. What is the total percent decrease from the original?', 'The remaining fraction is \(0.90 \times 0.90 = 0.81\), a \(19\%\) total decrease.', 'mc', '["\\(20\\%\\)","\\(21\\%\\)","\\(19\\%\\)","\\(1\\%\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0062', 'arithmetic-percentages', 'A team won \(60\%\) of its first \(20\) games and \(75\%\) of its next \(20\) games. Over all \(40\) games, what percent did it win?', 'Wins: \(0.60 \times 20 + 0.75 \times 20 = 12 + 15 = 27\); \(\tfrac{27}{40} = 67.5\%\).', 'mc', '["\\(67\\%\\)","\\(135\\%\\)","\\(70\\%\\)","\\(67.5\\%\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0063', 'arithmetic-percentages', 'A price is increased by \(20\%\), then the new price is decreased by \(15\%\). What is the net percent change from the original?', 'The combined factor is \(1.20 \times 0.85 = 1.02\), a net increase of \(2\%\).', 'mc', '["an increase of \\(2\\%\\)","an increase of \\(5\\%\\)","a decrease of \\(2\\%\\)","no change"]'::jsonb, 0, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0064', 'arithmetic-percentages', 'A \(50\)-liter mixture is \(40\%\) acid. How many liters of pure acid must be added to make the mixture \(50\%\) acid?', 'Start with \(20\) L acid in \(50\) L. Adding \(x\) L acid: \(\tfrac{20 + x}{50 + x} = 0.5\). Then \(20 + x = 25 + 0.5x\), so \(0.5x = 5\), \(x = 10\).', 'mc', '["\\(5\\)","\\(10\\)","\\(25\\)","\\(12.5\\)"]'::jsonb, 1, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0065', 'arithmetic-percentages', 'A store''s revenue rose \(25\%\) while the number of items sold fell \(20\%\). By what percent did the average price per item change?', 'Price factor is \(\tfrac{1.25}{0.80} = 1.5625\), an increase of \(56.25\%\).', 'mc', '["increased by \\(5\\%\\)","increased by \\(25\\%\\)","increased by \\(56.25\\%\\)","decreased by \\(20\\%\\)"]'::jsonb, 2, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0066', 'arithmetic-percentages', 'A blend mixes coffee A (costing \(8\) dollars per pound) and coffee B (\(12\) dollars per pound) to sell at \(9\) dollars per pound. What is the ratio of A to B, by weight?', 'Using alligation, the distances from \(9\) are \(12 - 9 = 3\) (for A) and \(9 - 8 = 1\) (for B), so A:B \(= 3:1\).', 'mc', '["\\(1:3\\)","\\(1:1\\)","\\(2:3\\)","\\(3:1\\)"]'::jsonb, 3, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0067', 'arithmetic-percentages', 'The ratio of men to women at an event was \(3:2\). After \(20\) more women arrived, the ratio became \(3:4\). How many men were present?', 'Let men \(= 3k\), women \(= 2k\). Then \(\tfrac{3k}{2k + 20} = \tfrac34\), so \(12k = 6k + 60\), \(k = 10\); men \(= 30\).', 'mc', '["\\(30\\)","\\(20\\)","\\(45\\)","\\(15\\)"]'::jsonb, 0, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0068', 'arithmetic-percentages', 'An alloy is \(60\%\) copper. How many kilograms of pure copper must be added to \(40\) kg of the alloy to raise the copper content to \(75\%\)?', 'Copper starts at \(24\) kg. Adding \(x\): \(\tfrac{24 + x}{40 + x} = 0.75\). Then \(24 + x = 30 + 0.75x\), so \(0.25x = 6\), \(x = 24\).', 'mc', '["\\(15\\)","\\(24\\)","\\(10\\)","\\(30\\)"]'::jsonb, 1, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0069', 'arithmetic-percentages', 'After a \(30\%\) discount and an additional \(10\%\) off the discounted price, a coat costs \(63\) dollars. What was the original price, in dollars?', 'The price factor is \(0.70 \times 0.90 = 0.63\), so \(0.63 x = 63\) gives \(x = 100\) dollars.', 'mc', '["\\(90\\)","\\(105\\)","\\(100\\)","\\(78.75\\)"]'::jsonb, 2, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('arith-0070', 'arithmetic-percentages', 'Two investments total \(10{,}000\) dollars. One earns \(5\%\) and the other \(8\%\) simple annual interest; together they earn \(680\) dollars in one year. How much was invested at \(8\%\), in dollars?', 'Let \(x\) be at \(8\%\): \(0.08x + 0.05(10000 - x) = 680\). Then \(0.03x = 180\), so \(x = 6000\) dollars.', 'mc', '["\\(4000\\)","\\(6800\\)","\\(5000\\)","\\(6000\\)"]'::jsonb, 3, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('alg-0064', 'algebra-equations', 'Solve for \(x\): \(3x + 7 = 22\).', 'Subtract \(7\): \(3x = 15\). Divide by \(3\): \(x = 5\).', 'mc', '["\\(5\\)","\\(7\\)","\\(9\\)","\\(3\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('alg-0065', 'algebra-equations', 'Solve for \(x\): \(5x - 4 = 26\).', 'Add \(4\): \(5x = 30\). Divide by \(5\): \(x = 6\).', 'mc', '["\\(5\\)","\\(6\\)","\\(4.4\\)","\\(30\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('alg-0066', 'algebra-equations', 'Solve for \(x\): \(\dfrac{x}{4} = 9\).', 'Multiply both sides by \(4\): \(x = 36\).', 'mc', '["\\(2.25\\)","\\(13\\)","\\(36\\)","\\(5\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('alg-0067', 'algebra-equations', 'If \(2(x - 3) = 10\), what is \(x\)?', 'Divide by \(2\): \(x - 3 = 5\), so \(x = 8\). (Or distribute: \(2x - 6 = 10\).)', 'mc', '["\\(5\\)","\\(2\\)","\\(6.5\\)","\\(8\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('alg-0068', 'algebra-equations', 'Solve for \(x\): \(7x = 4x + 15\).', 'Subtract \(4x\): \(3x = 15\), so \(x = 5\).', 'mc', '["\\(5\\)","\\(15\\)","\\(3\\)","\\(1.36\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('alg-0069', 'algebra-equations', 'Solve for \(x\): \(x + 12 = 3x\).', 'Subtract \(x\): \(12 = 2x\), so \(x = 6\).', 'mc', '["\\(3\\)","\\(6\\)","\\(4\\)","\\(12\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('alg-0070', 'algebra-equations', 'If \(4x + 1 = 2x + 9\), what is \(x\)?', 'Subtract \(2x\): \(2x + 1 = 9\); subtract \(1\): \(2x = 8\), so \(x = 4\).', 'mc', '["\\(5\\)","\\(2\\)","\\(4\\)","\\(1.67\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('alg-0071', 'algebra-equations', 'Solve for \(x\): \(\dfrac{2x + 1}{3} = 5\).', 'Multiply by \(3\): \(2x + 1 = 15\). Then \(2x = 14\), so \(x = 7\).', 'mc', '["\\(8\\)","\\(2\\)","\\(2.33\\)","\\(7\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('alg-0072', 'algebra-equations', 'If \(9 - 2x = 1\), what is \(x\)?', 'Subtract \(9\): \(-2x = -8\); divide by \(-2\): \(x = 4\).', 'mc', '["\\(4\\)","\\(-4\\)","\\(5\\)","\\(2.5\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('alg-0073', 'algebra-equations', 'Solve for \(x\): \(3(2x - 1) = 2(x + 5) + 3\).', 'Expand: \(6x - 3 = 2x + 13\). Then \(4x = 16\), so \(x = 4\).', 'mc', '["\\(4\\)","\\(2\\)","\\(5\\)","\\(2.75\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('alg-0074', 'algebra-equations', 'If \(\dfrac{x + 1}{3} = \dfrac{x - 5}{2}\), what is \(x\)?', 'Cross-multiply: \(2(x + 1) = 3(x - 5)\), so \(2x + 2 = 3x - 15\). Then \(x = 17\).', 'mc', '["\\(6\\)","\\(17\\)","\\(-13\\)","\\(11\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('alg-0075', 'algebra-equations', 'The formula \(P = 2l + 2w\) gives the perimeter of a rectangle. If \(P = 40\) and \(w = 7\), what is \(l\)?', 'Substitute: \(40 = 2l + 14\), so \(2l = 26\) and \(l = 13\).', 'mc', '["\\(26\\)","\\(16.5\\)","\\(13\\)","\\(33\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('alg-0076', 'algebra-equations', 'Solve for \(x\): \(0.2x + 1.5 = 0.5x - 0.6\).', 'Subtract \(0.2x\): \(1.5 = 0.3x - 0.6\); add \(0.6\): \(2.1 = 0.3x\), so \(x = 7\).', 'mc', '["\\(3\\)","\\(-7\\)","\\(0.3\\)","\\(7\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('lin-0039', 'linear-functions', 'A line has slope \(2\) and passes through \((0, 3)\). What is its equation?', 'Slope-intercept form \(y = mx + b\) with \(m = 2\), \(b = 3\).', 'mc', '["\\(y = 2x + 3\\)","\\(y = 3x + 2\\)","\\(y = 2x - 3\\)","\\(y = 3x - 2\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('lin-0040', 'linear-functions', 'What is the slope of the line \(y = -4x + 1\)?', 'In \(y = mx + b\), the slope is the coefficient of \(x\), which is \(-4\).', 'mc', '["\\(1\\)","\\(-4\\)","\\(4\\)","\\(-\\tfrac14\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('lin-0041', 'linear-functions', 'What is the \(y\)-intercept of \(y = 5x - 8\)?', 'The \(y\)-intercept is \(b = -8\), the value of \(y\) when \(x = 0\).', 'mc', '["\\(5\\)","\\(8\\)","\\(-8\\)","\\(1.6\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('lin-0042', 'linear-functions', 'Find the slope of the line through \((1, 2)\) and \((4, 11)\).', 'Slope \(= \dfrac{11 - 2}{4 - 1} = \dfrac{9}{3} = 3\).', 'mc', '["\\(\\tfrac13\\)","\\(9\\)","\\(13\\)","\\(3\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('lin-0043', 'linear-functions', 'A line passes through \((2, 5)\) and \((6, 5)\). What is its slope?', 'The \(y\)-values are equal, so the line is horizontal and its slope is \(0\).', 'mc', '["\\(0\\)","undefined","\\(1\\)","\\(5\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('lin-0044', 'linear-functions', 'If \(f(x) = 3x - 4\), what is \(f(2)\)?', 'Substitute: \(f(2) = 3(2) - 4 = 2\).', 'mc', '["\\(10\\)","\\(2\\)","\\(-4\\)","\\(6\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('lin-0045', 'linear-functions', 'If \(f(x) = -2x + 7\), what is \(f(0)\)?', '\(f(0) = -2(0) + 7 = 7\).', 'mc', '["\\(0\\)","\\(5\\)","\\(7\\)","\\(-2\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('lin-0046', 'linear-functions', 'What is the \(x\)-intercept of \(y = 2x - 6\)?', 'Set \(y = 0\): \(0 = 2x - 6\), so \(x = 3\).', 'mc', '["\\(-6\\)","\\(6\\)","\\(-3\\)","\\(3\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('lin-0047', 'linear-functions', 'A line has slope \(-3\) and \(y\)-intercept \(4\). What is its equation?', 'Use \(y = mx + b\) with \(m = -3\) and \(b = 4\).', 'mc', '["\\(y = -3x + 4\\)","\\(y = 4x - 3\\)","\\(y = -3x - 4\\)","\\(y = 3x + 4\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('lin-0048', 'linear-functions', 'For \(f(x) = \tfrac12 x + 1\), what is \(f(6)\)?', '\(f(6) = \tfrac12(6) + 1 = 3 + 1 = 4\).', 'mc', '["\\(3\\)","\\(4\\)","\\(7\\)","\\(13\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('lin-0049', 'linear-functions', 'What is the slope of the line \(2y = 6x + 10\)?', 'Divide by \(2\): \(y = 3x + 5\). The slope is \(3\).', 'mc', '["\\(6\\)","\\(5\\)","\\(3\\)","\\(2\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('lin-0050', 'linear-functions', 'Find the slope of the line through \((-2, 1)\) and \((2, 9)\).', 'Slope \(= \dfrac{9 - 1}{2 - (-2)} = \dfrac{8}{4} = 2\).', 'mc', '["\\(\\tfrac12\\)","\\(4\\)","\\(8\\)","\\(2\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('lin-0051', 'linear-functions', 'A vertical line passes through \((3, 7)\). What is its equation?', 'A vertical line has the form \(x = a\); here it passes through \(x = 3\).', 'mc', '["\\(x = 3\\)","\\(y = 7\\)","\\(y = 3\\)","\\(x = 7\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('lin-0052', 'linear-functions', 'If \(y = 4x\), what is \(y\) when \(x = 2.5\)?', '\(y = 4 \times 2.5 = 10\).', 'mc', '["\\(6.5\\)","\\(10\\)","\\(1.6\\)","\\(8\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('lin-0053', 'linear-functions', 'The line \(y = -x + 5\) has what slope?', 'The coefficient of \(x\) is \(-1\), so the slope is \(-1\).', 'mc', '["\\(1\\)","\\(5\\)","\\(-1\\)","\\(-5\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('lin-0054', 'linear-functions', 'What is the value of \(x\) when \(y = 0\) for \(y = -3x + 12\)?', 'Set \(0 = -3x + 12\), so \(3x = 12\) and \(x = 4\).', 'mc', '["\\(12\\)","\\(-4\\)","\\(-12\\)","\\(4\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('lin-0055', 'linear-functions', 'A line passes through \((0, -2)\) with slope \(3\). What is \(y\) when \(x = 4\)?', 'The line is \(y = 3x - 2\), so \(y = 3(4) - 2 = 10\).', 'mc', '["\\(10\\)","\\(12\\)","\\(6\\)","\\(1\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('lin-0056', 'linear-functions', 'If \(f(x) = 2x + 5\), for what \(x\) is \(f(x) = 17\)?', 'Solve \(2x + 5 = 17\): \(2x = 12\), so \(x = 6\).', 'mc', '["\\(11\\)","\\(6\\)","\\(39\\)","\\(12\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('lin-0057', 'linear-functions', 'Which point lies on the line \(y = 2x - 1\)?', 'Check \((3, 5)\): \(2(3) - 1 = 5\). It satisfies the equation.', 'mc', '["\\((3, 7)\\)","\\((1, 3)\\)","\\((3, 5)\\)","\\((0, 1)\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('lin-0058', 'linear-functions', 'A line has slope \(\tfrac25\). If \(x\) increases by \(10\), how much does \(y\) increase?', 'Change in \(y\) is slope times change in \(x\): \(\tfrac25 \times 10 = 4\).', 'mc', '["\\(25\\)","\\(2\\)","\\(20\\)","\\(4\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('lin-0059', 'linear-functions', 'What is the slope of a line parallel to \(y = 7x - 2\)?', 'Parallel lines have equal slopes, so the slope is \(7\).', 'mc', '["\\(7\\)","\\(-2\\)","\\(-\\tfrac17\\)","\\(2\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('lin-0060', 'linear-functions', 'Rewrite \(4x + 2y = 8\) in slope-intercept form.', 'Solve for \(y\): \(2y = -4x + 8\), so \(y = -2x + 4\).', 'mc', '["\\(y = 2x + 4\\)","\\(y = -2x + 4\\)","\\(y = -2x + 8\\)","\\(y = 4x + 2\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('lin-0061', 'linear-functions', 'A line passes through \((1, 4)\) and \((3, 10)\). What is its equation in slope-intercept form?', 'Slope \(= \dfrac{10 - 4}{3 - 1} = 3\). Using \((1, 4)\): \(4 = 3(1) + b\), so \(b = 1\).', 'mc', '["\\(y = 3x + 1\\)","\\(y = 3x - 1\\)","\\(y = 2x + 2\\)","\\(y = 3x + 4\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('lin-0062', 'linear-functions', 'A taxi charges a \(3\) dollar base fee plus \(2\) dollars per mile. Which function gives the cost \(C\) for \(m\) miles?', 'The base fee is the constant and the per-mile rate is the slope: \(C = 2m + 3\).', 'mc', '["\\(C = 3m + 2\\)","\\(C = 2m + 3\\)","\\(C = 2m - 3\\)","\\(C = 5m\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('lin-0063', 'linear-functions', 'The line through \((2, 7)\) is perpendicular to \(y = 2x + 1\). What is its slope?', 'Perpendicular slopes are negative reciprocals: the negative reciprocal of \(2\) is \(-\tfrac12\).', 'mc', '["\\(2\\)","\\(-2\\)","\\(-\\tfrac12\\)","\\(\\tfrac12\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('lin-0064', 'linear-functions', 'A candle burns at a constant rate. It is \(12\) cm tall after \(2\) hours and \(6\) cm tall after \(5\) hours. What was its original height, in cm?', 'Rate \(= \dfrac{6 - 12}{5 - 2} = -2\) cm/hr. At \(t = 0\): height \(= 12 - (-2)(2) = 16\) cm.', 'mc', '["\\(18\\)","\\(14\\)","\\(12\\)","\\(16\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('lin-0065', 'linear-functions', 'For the line \(3x - 4y = 12\), what is the \(y\)-intercept?', 'Set \(x = 0\): \(-4y = 12\), so \(y = -3\).', 'mc', '["\\(-3\\)","\\(4\\)","\\(-4\\)","\\(3\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('lin-0066', 'linear-functions', 'A line has \(x\)-intercept \(4\) and \(y\)-intercept \(-8\). What is its slope?', 'Slope \(= \dfrac{-8 - 0}{0 - 4} = \dfrac{-8}{-4} = 2\).', 'mc', '["\\(-2\\)","\\(2\\)","\\(\\tfrac12\\)","\\(-32\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('lin-0067', 'linear-functions', 'If \(f(x) = mx + b\), \(f(2) = 9\), and \(f(5) = 21\), what is \(m\)?', 'Slope \(m = \dfrac{21 - 9}{5 - 2} = \dfrac{12}{3} = 4\).', 'mc', '["\\(3\\)","\\(12\\)","\\(4\\)","\\(6\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('lin-0068', 'linear-functions', 'A gym membership costs \(20\) dollars to join plus \(15\) dollars per month. After how many months does the total reach \(155\) dollars?', 'Solve \(15x + 20 = 155\): \(15x = 135\), so \(x = 9\) months.', 'mc', '["\\(10.3\\)","\\(11\\)","\\(7\\)","\\(9\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('lin-0069', 'linear-functions', 'Line \(k\) passes through \((-3, 2)\) and is perpendicular to the line \(2x + 5y = 10\). What is the equation of line \(k\)?', 'The given line has slope \(-\tfrac25\), so line \(k\) has slope \(\tfrac52\). Through \((-3, 2)\): \(2 = \tfrac52(-3) + b\), so \(b = 2 + \tfrac{15}{2} = \tfrac{19}{2}\).', 'mc', '["\\(y = \\tfrac52 x + \\tfrac{19}{2}\\)","\\(y = -\\tfrac25 x + \\tfrac{4}{5}\\)","\\(y = \\tfrac52 x - \\tfrac{19}{2}\\)","\\(y = -\\tfrac52 x + 2\\)"]'::jsonb, 0, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('lin-0070', 'linear-functions', 'A line passes through \((1, a)\) and \((a, 7)\) and has slope \(2\). What is the value of \(a\)?', 'Slope \(= \dfrac{7 - a}{a - 1} = 2\). Then \(7 - a = 2(a - 1) = 2a - 2\), so \(9 = 3a\) and \(a = 3\). Check: \((1, 3)\) and \((3, 7)\) give slope \(\tfrac{4}{2} = 2\).', 'mc', '["\\(9\\)","\\(3\\)","\\(5\\)","\\(4\\)"]'::jsonb, 1, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0016', 'systems-of-equations', 'If \(x + y = 7\) and \(x - y = 3\), what is the value of \(x\)?', 'Solving the system gives \(x = 5\) and \(y = 2\). So \(x = 5\).', 'mc', '["\\(5\\)","\\(2\\)","\\(-5\\)","\\(6\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0017', 'systems-of-equations', 'If \(x + y = 7\) and \(x - y = 3\), what is the value of \(y\)?', 'Solving the system gives \(x = 5\) and \(y = 2\). So \(y = 2\).', 'mc', '["\\(5\\)","\\(2\\)","\\(-2\\)","\\(3\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0018', 'systems-of-equations', 'If \(2x + y = 7\) and \(x - y = 2\), what is the value of \(x\)?', 'Solving the system gives \(x = 3\) and \(y = 1\). So \(x = 3\).', 'mc', '["\\(1\\)","\\(-3\\)","\\(3\\)","\\(4\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0019', 'systems-of-equations', 'If \(x + 2y = 6\) and \(x - y = 3\), what is the value of \(y\)?', 'Solving the system gives \(x = 4\) and \(y = 1\). So \(y = 1\).', 'mc', '["\\(4\\)","\\(-1\\)","\\(2\\)","\\(1\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0020', 'systems-of-equations', 'If \(x + y = 10\) and \(2x + y = 16\), what is the value of \(x\)?', 'Solving the system gives \(x = 6\) and \(y = 4\). So \(x = 6\).', 'mc', '["\\(6\\)","\\(4\\)","\\(-6\\)","\\(7\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0021', 'systems-of-equations', 'If \(x + y = 10\) and \(2x + y = 17\), what is the value of \(y\)?', 'Solving the system gives \(x = 7\) and \(y = 3\). So \(y = 3\).', 'mc', '["\\(7\\)","\\(3\\)","\\(-3\\)","\\(4\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0022', 'systems-of-equations', 'If \(3x + y = 9\) and \(x - y = -1\), what is the value of \(x + y\)?', 'Solving the system gives \(x = 2\) and \(y = 3\). So \(x + y = 5\).', 'mc', '["\\(-1\\)","\\(2\\)","\\(5\\)","\\(3\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0023', 'systems-of-equations', 'If \(x + y = 11\) and \(x + 2y = 14\), what is the value of \(x\)?', 'Solving the system gives \(x = 8\) and \(y = 3\). So \(x = 8\).', 'mc', '["\\(3\\)","\\(-8\\)","\\(9\\)","\\(8\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0024', 'systems-of-equations', 'If \(2x - y = 6\) and \(x + y = 6\), what is the value of \(y\)?', 'Solving the system gives \(x = 4\) and \(y = 2\). So \(y = 2\).', 'mc', '["\\(2\\)","\\(4\\)","\\(-2\\)","\\(3\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0025', 'systems-of-equations', 'If \(x - 2y = 3\) and \(2x + y = 11\), what is the value of \(x\)?', 'Solving the system gives \(x = 5\) and \(y = 1\). So \(x = 5\).', 'mc', '["\\(1\\)","\\(5\\)","\\(-5\\)","\\(6\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0026', 'systems-of-equations', 'If \(x + y = 9\) and \(3x - y = 7\), what is the value of \(x - y\)?', 'Solving the system gives \(x = 4\) and \(y = 5\). So \(x - y = -1\).', 'mc', '["\\(9\\)","\\(1\\)","\\(-1\\)","\\(0\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0027', 'systems-of-equations', 'If \(2x + 3y = 16\) and \(x - y = -2\), what is the value of \(x + y\)?', 'Solving the system gives \(x = 2\) and \(y = 4\). So \(x + y = 6\).', 'mc', '["\\(-2\\)","\\(2\\)","\\(4\\)","\\(6\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0028', 'systems-of-equations', 'If \(x + 4y = 14\) and \(x + y = 5\), what is the value of \(y\)?', 'Solving the system gives \(x = 2\) and \(y = 3\). So \(y = 3\).', 'mc', '["\\(3\\)","\\(2\\)","\\(-3\\)","\\(4\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0029', 'systems-of-equations', 'Two pencils and one pen cost \(5\) dollars. One pencil and one pen cost \(4\) dollars. What is the cost of one pen, in dollars?', 'Subtracting the equations \((2p + q) - (p + q) = 5 - 4\) gives \(p = 1\) (pencil). Then \(q = 4 - 1 = 3\) dollars.', 'mc', '["\\(1\\)","\\(3\\)","\\(2\\)","\\(4\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0030', 'systems-of-equations', 'The sum of two numbers is \(20\) and their difference is \(6\). What is the larger number?', 'Adding \(x + y = 20\) and \(x - y = 6\) gives \(2x = 26\), so \(x = 13\).', 'mc', '["\\(7\\)","\\(14\\)","\\(13\\)","\\(10\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0031', 'systems-of-equations', 'An adult ticket costs \(9\) dollars and a child ticket \(5\) dollars. A family buys \(2\) adult and \(3\) child tickets. What is the total cost, in dollars?', 'Total \(= 2(9) + 3(5) = 18 + 15 = 33\) dollars.', 'mc', '["\\(24\\)","\\(45\\)","\\(14\\)","\\(33\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0032', 'systems-of-equations', 'A number \(x\) is twice a number \(y\), and \(x + y = 18\). What is \(y\)?', 'Substitute \(x = 2y\): \(2y + y = 18\), so \(3y = 18\) and \(y = 6\).', 'mc', '["\\(6\\)","\\(12\\)","\\(9\\)","\\(3\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0033', 'systems-of-equations', 'Three apples and two bananas cost \(7\) dollars. An apple costs \(1\) dollar. What does a banana cost, in dollars?', 'With apples at \(1\): \(3(1) + 2b = 7\), so \(2b = 4\) and \(b = 2\) dollars.', 'mc', '["\\(3\\)","\\(2\\)","\\(4\\)","\\(1.5\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0034', 'systems-of-equations', 'The perimeter of a rectangle is \(30\), and its length is \(3\) more than its width. What is the width?', 'With \(l = w + 3\) and \(2l + 2w = 30\): \(2(w + 3) + 2w = 30\), so \(4w = 24\) and \(w = 6\).', 'mc', '["\\(9\\)","\\(12\\)","\\(6\\)","\\(7.5\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0035', 'systems-of-equations', 'A jar has nickels and dimes totaling \(8\) coins worth \(65\) cents. How many dimes are there?', 'With \(n + d = 8\) and \(5n + 10d = 65\): substitute \(n = 8 - d\) to get \(5(8 - d) + 10d = 65\), so \(5d = 25\) and \(d = 5\).', 'mc', '["\\(3\\)","\\(4\\)","\\(6\\)","\\(5\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0036', 'systems-of-equations', 'Two numbers add to \(15\). One is four times the other. What is the smaller number?', 'With \(x = 4y\) and \(x + y = 15\): \(5y = 15\), so \(y = 3\).', 'mc', '["\\(3\\)","\\(12\\)","\\(5\\)","\\(4\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0037', 'systems-of-equations', 'A store sells notebooks at \(3\) dollars and folders at \(2\) dollars. Someone buys \(4\) notebooks and some folders for \(20\) dollars total. How many folders?', 'With \(4(3) + 2f = 20\): \(2f = 8\), so \(f = 4\).', 'mc', '["\\(6\\)","\\(4\\)","\\(3\\)","\\(5\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0038', 'systems-of-equations', 'The difference of two numbers is \(10\) and their sum is \(24\). What is the smaller number?', 'From \(x + y = 24\) and \(x - y = 10\), subtracting gives \(2y = 14\), so \(y = 7\).', 'mc', '["\\(17\\)","\\(14\\)","\\(7\\)","\\(12\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0039', 'systems-of-equations', 'A bike costs \(3\) times as much as a helmet. Together they cost \(160\) dollars. What does the helmet cost, in dollars?', 'With \(b = 3h\) and \(b + h = 160\): \(4h = 160\), so \(h = 40\) dollars.', 'mc', '["\\(120\\)","\\(53.3\\)","\\(80\\)","\\(40\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0040', 'systems-of-equations', 'Two coffees and a muffin cost \(11\) dollars; one coffee and a muffin cost \(7\) dollars. What does one coffee cost, in dollars?', 'Subtracting the equations gives one coffee \(= 11 - 7 = 4\) dollars.', 'mc', '["\\(4\\)","\\(3\\)","\\(7\\)","\\(5.5\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0041', 'systems-of-equations', 'A rectangle''s length is twice its width, and its perimeter is \(36\). What is the length?', 'With \(l = 2w\): \(2(2w) + 2w = 36\), so \(6w = 36\), \(w = 6\), and \(l = 12\).', 'mc', '["\\(6\\)","\\(12\\)","\\(9\\)","\\(18\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0042', 'systems-of-equations', 'If \(3x + 2y = 14\) and \(2x - y = 7\), what is the value of \(x\)?', 'Solving the system gives \(x = 4\) and \(y = 1\). So \(x = 4\).', 'mc', '["\\(4\\)","\\(1\\)","\\(-4\\)","\\(5\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0043', 'systems-of-equations', 'If \(3x + 2y = 14\) and \(2x - y = 7\), what is the value of \(y\)?', 'Solving the system gives \(x = 4\) and \(y = 1\). So \(y = 1\).', 'mc', '["\\(4\\)","\\(1\\)","\\(-1\\)","\\(2\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0044', 'systems-of-equations', 'If \(2x + 3y = 12\) and \(4x - y = 10\), what is the value of \(x\)?', 'Solving the system gives \(x = 3\) and \(y = 2\). So \(x = 3\).', 'mc', '["\\(2\\)","\\(-3\\)","\\(3\\)","\\(4\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0045', 'systems-of-equations', 'If \(5x + 2y = 12\) and \(3x - 4y = 2\), what is the value of \(y\)?', 'Solving the system gives \(x = 2\) and \(y = 1\). So \(y = 1\).', 'mc', '["\\(2\\)","\\(-1\\)","\\(0\\)","\\(1\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0046', 'systems-of-equations', 'If \(4x - 3y = 6\) and \(2x + 5y = 16\), what is the value of \(x + y\)?', 'Solving the system gives \(x = 3\) and \(y = 2\). So \(x + y = 5\).', 'mc', '["\\(5\\)","\\(1\\)","\\(3\\)","\\(2\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0047', 'systems-of-equations', 'If \(3x + 4y = 18\) and \(5x - 2y = 4\), what is the value of \(x\)?', 'Solving the system gives \(x = 2\) and \(y = 3\). So \(x = 2\).', 'mc', '["\\(3\\)","\\(2\\)","\\(-2\\)","\\(1\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0048', 'systems-of-equations', 'If \(2x + 5y = 5\) and \(3x + 2y = 13\), what is the value of \(y\)?', 'Solving the system gives \(x = 5\) and \(y = -1\). So \(y = -1\).', 'mc', '["\\(5\\)","\\(1\\)","\\(-1\\)","\\(0\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0049', 'systems-of-equations', 'If \(6x + y = 10\) and \(2x - 3y = -10\), what is the value of \(x - y\)?', 'Solving the system gives \(x = 1\) and \(y = 4\). So \(x - y = -3\).', 'mc', '["\\(5\\)","\\(3\\)","\\(-2\\)","\\(-3\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0050', 'systems-of-equations', 'If \(3x - 2y = 2\) and \(4x + 3y = 31\), what is the value of \(x\)?', 'Solving the system gives \(x = 4\) and \(y = 5\). So \(x = 4\).', 'mc', '["\\(4\\)","\\(5\\)","\\(-4\\)","\\(3\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0051', 'systems-of-equations', 'If \(5x + 3y = 9\) and \(2x + 7y = -8\), what is the value of \(x + y\)?', 'Solving the system gives \(x = 3\) and \(y = -2\). So \(x + y = 1\).', 'mc', '["\\(5\\)","\\(1\\)","\\(3\\)","\\(-2\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0052', 'systems-of-equations', 'If \(7x + 2y = 13\) and \(3x - y = 0\), what is the value of \(y\)?', 'Solving the system gives \(x = 1\) and \(y = 3\). So \(y = 3\).', 'mc', '["\\(1\\)","\\(-3\\)","\\(3\\)","\\(4\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0053', 'systems-of-equations', 'If \(4x + 5y = 28\) and \(6x - y = 8\), what is the value of \(x\)?', 'Solving the system gives \(x = 2\) and \(y = 4\). So \(x = 2\).', 'mc', '["\\(4\\)","\\(-2\\)","\\(3\\)","\\(2\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0054', 'systems-of-equations', 'A theater sold \(200\) tickets for \(1{,}400\) dollars. Adult tickets are \(9\) dollars and student tickets \(5\) dollars. How many adult tickets were sold?', 'With \(a + s = 200\) and \(9a + 5s = 1400\): substitute \(s = 200 - a\) to get \(9a + 1000 - 5a = 1400\), so \(4a = 400\) and \(a = 100\).', 'mc', '["\\(100\\)","\\(75\\)","\\(125\\)","\\(80\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0055', 'systems-of-equations', 'A chemist mixes a \(20\%\) solution with a \(50\%\) solution to make \(30\) liters of \(30\%\) solution. How many liters of the \(20\%\) solution are used?', 'With \(x + y = 30\) and \(0.2x + 0.5y = 0.3(30) = 9\): from the first \(y = 30 - x\), so \(0.2x + 0.5(30 - x) = 9\), giving \(-0.3x = -6\), \(x = 20\).', 'mc', '["\\(10\\)","\\(20\\)","\\(15\\)","\\(25\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0056', 'systems-of-equations', 'The sum of two numbers is \(50\). Three times the smaller equals twice the larger. What is the larger number?', 'With \(x + y = 50\) and \(3y = 2x\) (\(y\) smaller): \(y = \tfrac{2x}{3}\), so \(x + \tfrac{2x}{3} = 50\), giving \(\tfrac{5x}{3} = 50\), \(x = 30\).', 'mc', '["\\(20\\)","\\(25\\)","\\(30\\)","\\(33.3\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0057', 'systems-of-equations', 'A boat travels \(24\) miles downstream in \(2\) hours and the same \(24\) miles upstream in \(3\) hours. What is the speed of the boat in still water, in miles per hour?', 'Downstream \(b + c = 12\), upstream \(b - c = 8\). Adding: \(2b = 20\), so \(b = 10\) miles per hour.', 'mc', '["\\(2\\)","\\(12\\)","\\(8\\)","\\(10\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0058', 'systems-of-equations', 'Two angles are complementary. One is \(30\) degrees larger than the other. What is the measure of the smaller angle, in degrees?', 'With \(x + y = 90\) and \(x - y = 30\): subtracting gives \(2y = 60\), so \(y = 30\) degrees.', 'mc', '["\\(30\\)","\\(60\\)","\\(45\\)","\\(15\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0059', 'systems-of-equations', 'A vendor sells hot dogs for \(3\) dollars and drinks for \(2\) dollars. In one hour he sells \(20\) items for \(52\) dollars. How many hot dogs did he sell?', 'With \(h + d = 20\) and \(3h + 2d = 52\): substitute \(d = 20 - h\) to get \(3h + 40 - 2h = 52\), so \(h = 12\).', 'mc', '["\\(8\\)","\\(12\\)","\\(10\\)","\\(14\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0060', 'systems-of-equations', 'The tens digit of a two-digit number is \(2\) more than the units digit, and the digits sum to \(12\). What is the number?', 'With \(t = u + 2\) and \(t + u = 12\): \(2u + 2 = 12\), so \(u = 5\), \(t = 7\); the number is \(75\).', 'mc', '["\\(57\\)","\\(48\\)","\\(75\\)","\\(84\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0061', 'systems-of-equations', 'A \(10\)-pound mixture of nuts costs \(6\) dollars per pound. Peanuts cost \(4\) dollars per pound and cashews \(9\) dollars per pound. How many pounds of cashews are in the mix?', 'With \(p + c = 10\) and \(4p + 9c = 60\): substitute \(p = 10 - c\) to get \(40 - 4c + 9c = 60\), so \(5c = 20\), \(c = 4\).', 'mc', '["\\(6\\)","\\(5\\)","\\(3\\)","\\(4\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0062', 'systems-of-equations', 'Alice is \(4\) years older than Ben. In \(2\) years, the sum of their ages will be \(30\). How old is Ben now?', 'With \(a = b + 4\) and \((a + 2) + (b + 2) = 30\): \(a + b = 26\), so \((b + 4) + b = 26\), giving \(b = 11\).', 'mc', '["\\(11\\)","\\(15\\)","\\(13\\)","\\(9\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0063', 'systems-of-equations', 'A gym offers plan A at \(30\) dollars plus \(2\) dollars per visit and plan B at \(10\) dollars plus \(4\) dollars per visit. At how many visits do the plans cost the same?', 'Set \(30 + 2v = 10 + 4v\): \(20 = 2v\), so \(v = 10\) visits.', 'mc', '["\\(20\\)","\\(10\\)","\\(5\\)","\\(40\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0064', 'systems-of-equations', 'A rectangle has perimeter \(44\) and its length is \(4\) less than \(3\) times its width. What is the width?', 'With \(l = 3w - 4\) and \(2l + 2w = 44\) (so \(l + w = 22\)): \(3w - 4 + w = 22\), giving \(4w = 26\), \(w = 6.5\).', 'mc', '["\\(9\\)","\\(15.5\\)","\\(6.5\\)","\\(11\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0065', 'systems-of-equations', 'The sum of two numbers is \(3\) and twice the first minus the second is \(12\). What is the first number?', 'With \(x + y = 3\) and \(2x - y = 12\): adding gives \(3x = 15\), so \(x = 5\).', 'mc', '["\\(-2\\)","\\(4\\)","\\(7\\)","\\(5\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0066', 'systems-of-equations', 'A farmer has chickens and cows totaling \(30\) animals with \(74\) legs. How many cows are there?', 'With \(c + k = 30\) and \(2c + 4k = 74\) (\(k\) cows): substitute \(c = 30 - k\) to get \(60 - 2k + 4k = 74\), so \(2k = 14\), \(k = 7\).', 'mc', '["\\(7\\)","\\(23\\)","\\(15\\)","\\(8\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0067', 'systems-of-equations', 'The system \(\begin{cases} 3x + ky = 12 \\ 6x + 4y = 7 \end{cases}\) has no solution. What is \(k\)?', 'No solution means the lines are parallel: equal slopes. From \(3x + ky = 12\), slope \(= -\tfrac{3}{k}\); from \(6x + 4y = 7\), slope \(= -\tfrac{6}{4} = -\tfrac32\). Setting \(\tfrac{3}{k} = \tfrac32\) gives \(k = 2\).', 'mc', '["\\(2\\)","\\(8\\)","\\(4\\)","\\(\\tfrac12\\)"]'::jsonb, 0, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0068', 'systems-of-equations', 'For what value of \(c\) does the system \(\begin{cases} 2x - 3y = 5 \\ 4x - 6y = c \end{cases}\) have infinitely many solutions?', 'Infinitely many solutions requires the second equation to be a multiple of the first. Multiplying \(2x - 3y = 5\) by \(2\) gives \(4x - 6y = 10\), so \(c = 10\).', 'mc', '["\\(5\\)","\\(10\\)","\\(20\\)","\\(2.5\\)"]'::jsonb, 1, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0069', 'systems-of-equations', 'A two-digit number equals \(7\) times the sum of its digits. Reversing its digits gives a number \(18\) less than the original. What is the original number?', 'Let the number be \(10t + u\). Then \(10t + u = 7(t + u)\) gives \(3t = 6u\), so \(t = 2u\). Also \((10t + u) - (10u + t) = 18\) gives \(9(t - u) = 18\), so \(t - u = 2\). With \(t = 2u\): \(u = 2\), \(t = 4\); the number is \(42\).', 'mc', '["\\(24\\)","\\(63\\)","\\(42\\)","\\(21\\)"]'::jsonb, 2, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('sys-0070', 'systems-of-equations', 'Three pens and two notebooks cost \(16\) dollars, while two pens and five notebooks cost \(18\) dollars. What is the total cost of one pen and one notebook, in dollars?', 'With \(3p + 2n = 16\) and \(2p + 5n = 18\): solving gives \(p = 4\) and \(n = 2\), so \(p + n = 6\) dollars.', 'mc', '["\\(34\\)","\\(5\\)","\\(7\\)","\\(6\\)"]'::jsonb, 3, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0039', 'quadratics-polynomials', 'What are the solutions to \(x^2 - 5x + 6 = 0\)?', 'Factor: \(x^2 - 5x + 6 = (x - 2)(x - 3)\). Setting each factor to zero gives \(x = 2\) and \(x = 3\).', 'mc', '["\\(x = 2\\) and \\(x = 3\\)","\\(x = -2\\) and \\(x = -3\\)","\\(x = 2\\) and \\(x = -3\\)","\\(x = 3\\) and \\(x = 2\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0040', 'quadratics-polynomials', 'What are the solutions to \(x^2 - 5x + 4 = 0\)?', 'Factor: \(x^2 - 5x + 4 = (x - 1)(x - 4)\). Setting each factor to zero gives \(x = 1\) and \(x = 4\).', 'mc', '["\\(x = -1\\) and \\(x = -4\\)","\\(x = 1\\) and \\(x = 4\\)","\\(x = 1\\) and \\(x = -4\\)","\\(x = 2\\) and \\(x = 3\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0041', 'quadratics-polynomials', 'What are the solutions to \(x^2 - 8x + 15 = 0\)?', 'Factor: \(x^2 - 8x + 15 = (x - 3)(x - 5)\). Setting each factor to zero gives \(x = 3\) and \(x = 5\).', 'mc', '["\\(x = -3\\) and \\(x = -5\\)","\\(x = 3\\) and \\(x = -5\\)","\\(x = 3\\) and \\(x = 5\\)","\\(x = 4\\) and \\(x = 4\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0042', 'quadratics-polynomials', 'What are the solutions to \(x^2 - 8x + 12 = 0\)?', 'Factor: \(x^2 - 8x + 12 = (x - 2)(x - 6)\). Setting each factor to zero gives \(x = 2\) and \(x = 6\).', 'mc', '["\\(x = -2\\) and \\(x = -6\\)","\\(x = 2\\) and \\(x = -6\\)","\\(x = 3\\) and \\(x = 5\\)","\\(x = 2\\) and \\(x = 6\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0043', 'quadratics-polynomials', 'What are the solutions to \(x^2 - 8x + 7 = 0\)?', 'Factor: \(x^2 - 8x + 7 = (x - 1)(x - 7)\). Setting each factor to zero gives \(x = 1\) and \(x = 7\).', 'mc', '["\\(x = 1\\) and \\(x = 7\\)","\\(x = -1\\) and \\(x = -7\\)","\\(x = 1\\) and \\(x = -7\\)","\\(x = 2\\) and \\(x = 6\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0044', 'quadratics-polynomials', 'What are the solutions to \(x^2 - 9x + 20 = 0\)?', 'Factor: \(x^2 - 9x + 20 = (x - 4)(x - 5)\). Setting each factor to zero gives \(x = 4\) and \(x = 5\).', 'mc', '["\\(x = -4\\) and \\(x = -5\\)","\\(x = 4\\) and \\(x = 5\\)","\\(x = 4\\) and \\(x = -5\\)","\\(x = 5\\) and \\(x = 4\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0045', 'quadratics-polynomials', 'What are the solutions to \(x^2 - 6x + 8 = 0\)?', 'Factor: \(x^2 - 6x + 8 = (x - 2)(x - 4)\). Setting each factor to zero gives \(x = 2\) and \(x = 4\).', 'mc', '["\\(x = -2\\) and \\(x = -4\\)","\\(x = 2\\) and \\(x = -4\\)","\\(x = 2\\) and \\(x = 4\\)","\\(x = 3\\) and \\(x = 3\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0046', 'quadratics-polynomials', 'What are the solutions to \(x^2 + 5x + 6 = 0\)?', 'Factor: \(x^2 + 5x + 6 = (x - -2)(x - -3)\). Setting each factor to zero gives \(x = -2\) and \(x = -3\).', 'mc', '["\\(x = 2\\) and \\(x = 3\\)","\\(x = -2\\) and \\(x = 3\\)","\\(x = -1\\) and \\(x = -4\\)","\\(x = -2\\) and \\(x = -3\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0047', 'quadratics-polynomials', 'What are the solutions to \(x^2 + 6x + 5 = 0\)?', 'Factor: \(x^2 + 6x + 5 = (x - -1)(x - -5)\). Setting each factor to zero gives \(x = -1\) and \(x = -5\).', 'mc', '["\\(x = -1\\) and \\(x = -5\\)","\\(x = 1\\) and \\(x = 5\\)","\\(x = -1\\) and \\(x = 5\\)","\\(x = 0\\) and \\(x = -6\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0048', 'quadratics-polynomials', 'What are the solutions to \(x^2 - 7x + 12 = 0\)?', 'Factor: \(x^2 - 7x + 12 = (x - 3)(x - 4)\). Setting each factor to zero gives \(x = 3\) and \(x = 4\).', 'mc', '["\\(x = -3\\) and \\(x = -4\\)","\\(x = 3\\) and \\(x = 4\\)","\\(x = 3\\) and \\(x = -4\\)","\\(x = 4\\) and \\(x = 3\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0049', 'quadratics-polynomials', 'What are the solutions to \(x^2 - 3x - 10 = 0\)?', 'Factor: \(x^2 - 3x - 10 = (x - -2)(x - 5)\). Setting each factor to zero gives \(x = -2\) and \(x = 5\).', 'mc', '["\\(x = 2\\) and \\(x = -5\\)","\\(x = -2\\) and \\(x = -5\\)","\\(x = -2\\) and \\(x = 5\\)","\\(x = -1\\) and \\(x = 4\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0050', 'quadratics-polynomials', 'What are the solutions to \(x^2 - 7x + 6 = 0\)?', 'Factor: \(x^2 - 7x + 6 = (x - 1)(x - 6)\). Setting each factor to zero gives \(x = 1\) and \(x = 6\).', 'mc', '["\\(x = -1\\) and \\(x = -6\\)","\\(x = 1\\) and \\(x = -6\\)","\\(x = 2\\) and \\(x = 5\\)","\\(x = 1\\) and \\(x = 6\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0051', 'quadratics-polynomials', 'What are the solutions to \(x^2 + x - 6 = 0\)?', 'Factor: \(x^2 + x - 6 = (x - -3)(x - 2)\). Setting each factor to zero gives \(x = -3\) and \(x = 2\).', 'mc', '["\\(x = -3\\) and \\(x = 2\\)","\\(x = 3\\) and \\(x = -2\\)","\\(x = -3\\) and \\(x = -2\\)","\\(x = -2\\) and \\(x = 1\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0052', 'quadratics-polynomials', 'What are the solutions to \(x^2 - 11x + 30 = 0\)?', 'Factor: \(x^2 - 11x + 30 = (x - 5)(x - 6)\). Setting each factor to zero gives \(x = 5\) and \(x = 6\).', 'mc', '["\\(x = -5\\) and \\(x = -6\\)","\\(x = 5\\) and \\(x = 6\\)","\\(x = 5\\) and \\(x = -6\\)","\\(x = 6\\) and \\(x = 5\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0053', 'quadratics-polynomials', 'If \(f(x) = x^2 - 3x + 2\), what is \(f(4)\)?', '\(f(4) = 16 - 12 + 2 = 6\).', 'mc', '["\\(30\\)","\\(-6\\)","\\(6\\)","\\(14\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0054', 'quadratics-polynomials', 'Factor completely: \(x^2 - 9\).', 'This is a difference of squares: \(x^2 - 9 = (x - 3)(x + 3)\).', 'mc', '["\\((x - 3)^2\\)","\\((x - 9)(x + 1)\\)","\\((x + 3)^2\\)","\\((x - 3)(x + 3)\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0055', 'quadratics-polynomials', 'Expand \((x + 5)(x - 2)\).', 'Use FOIL: \(x^2 - 2x + 5x - 10 = x^2 + 3x - 10\).', 'mc', '["\\(x^2 + 3x - 10\\)","\\(x^2 - 3x - 10\\)","\\(x^2 + 7x - 10\\)","\\(x^2 + 3x + 10\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0056', 'quadratics-polynomials', 'What is the constant term of \((x - 4)(x + 6)\)?', 'The constant is the product of the constants: \((-4)(6) = -24\).', 'mc', '["\\(24\\)","\\(-24\\)","\\(2\\)","\\(-10\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0057', 'quadratics-polynomials', 'One solution of \(x^2 - 7x + 12 = 0\) is \(x = 3\). What is the other solution?', 'The roots multiply to \(12\): \(3 \cdot r = 12\), so \(r = 4\).', 'mc', '["\\(-4\\)","\\(7\\)","\\(4\\)","\\(-3\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0058', 'quadratics-polynomials', 'What is the \(y\)-intercept of \(y = x^2 - 2x - 8\)?', 'Set \(x = 0\): \(y = -8\).', 'mc', '["\\(8\\)","\\(-2\\)","\\(2\\)","\\(-8\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0059', 'quadratics-polynomials', 'Factor: \(x^2 + 6x + 9\).', 'This is a perfect square: \(x^2 + 6x + 9 = (x + 3)^2\).', 'mc', '["\\((x + 3)^2\\)","\\((x - 3)^2\\)","\\((x + 9)(x + 1)\\)","\\((x + 3)(x - 3)\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0060', 'quadratics-polynomials', 'Expand \((x - 3)^2\).', '\((x - 3)^2 = x^2 - 2(3)x + 9 = x^2 - 6x + 9\).', 'mc', '["\\(x^2 + 9\\)","\\(x^2 - 6x + 9\\)","\\(x^2 - 9\\)","\\(x^2 - 6x - 9\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0061', 'quadratics-polynomials', 'For \(f(x) = x^2 + x\), what is \(f(-3)\)?', '\(f(-3) = 9 + (-3) = 6\).', 'mc', '["\\(-6\\)","\\(12\\)","\\(6\\)","\\(-12\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0062', 'quadratics-polynomials', 'What value of \(x\) makes \(x^2 = 49\) with \(x > 0\)?', '\(x^2 = 49\) gives \(x = \pm 7\); the positive solution is \(7\).', 'mc', '["\\(24.5\\)","\\(-7\\)","\\(2401\\)","\\(7\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0063', 'quadratics-polynomials', 'Factor out the greatest common factor: \(6x^2 + 9x\).', 'The GCF of \(6x^2\) and \(9x\) is \(3x\): \(6x^2 + 9x = 3x(2x + 3)\).', 'mc', '["\\(3x(2x + 3)\\)","\\(3(2x^2 + 3x)\\)","\\(3x(2x + 9)\\)","\\(x(6x + 9)\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0064', 'quadratics-polynomials', 'The graph of \(y = (x - 2)^2 + 5\) has its vertex at which point?', 'In vertex form \(y = (x - h)^2 + k\), the vertex is \((h, k) = (2, 5)\).', 'mc', '["\\((-2, 5)\\)","\\((2, 5)\\)","\\((2, -5)\\)","\\((5, 2)\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0065', 'quadratics-polynomials', 'What is the \(x\)-coordinate of the vertex of \(y = x^2 - 6x + 5\)?', 'The vertex is at \(x = -\tfrac{b}{2a} = -\tfrac{-6}{2} = 3\).', 'mc', '["\\(3\\)","\\(-3\\)","\\(6\\)","\\(5\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0066', 'quadratics-polynomials', 'What are the solutions to \(2x^2 - 8x = 0\)?', 'Factor: \(2x(x - 4) = 0\), so \(x = 0\) or \(x = 4\).', 'mc', '["\\(x = 0\\) and \\(x = -4\\)","\\(x = 0\\) and \\(x = 4\\)","\\(x = 4\\) only","\\(x = 2\\) and \\(x = 4\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0067', 'quadratics-polynomials', 'For what value of \(k\) does \(x^2 + kx + 9 = 0\) have exactly one real solution, with \(k > 0\)?', 'One solution means discriminant \(= 0\): \(k^2 - 36 = 0\), so \(k = 6\) (taking \(k > 0\)).', 'mc', '["\\(3\\)","\\(9\\)","\\(6\\)","\\(18\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0068', 'quadratics-polynomials', 'The product of the roots of \(x^2 - 5x + 6 = 0\) is what?', 'For \(x^2 + bx + c\), the product of the roots is \(c = 6\).', 'mc', '["\\(5\\)","\\(-6\\)","\\(-5\\)","\\(6\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0069', 'quadratics-polynomials', 'What is the minimum value of \(y = x^2 - 4x + 7\)?', 'The vertex is at \(x = 2\); \(y = 4 - 8 + 7 = 3\), the minimum.', 'mc', '["\\(3\\)","\\(7\\)","\\(2\\)","\\(-3\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0070', 'quadratics-polynomials', 'Solve \(x^2 - 2x - 15 = 0\).', 'Factor: \((x - 5)(x + 3) = 0\), so \(x = 5\) or \(x = -3\).', 'mc', '["\\(x = -5\\) and \\(x = 3\\)","\\(x = 5\\) and \\(x = -3\\)","\\(x = 5\\) and \\(x = 3\\)","\\(x = 15\\) and \\(x = -1\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0071', 'quadratics-polynomials', 'Write \(x^2 + 8x + 10\) in vertex form.', 'Complete the square: \(x^2 + 8x + 16 - 16 + 10 = (x + 4)^2 - 6\).', 'mc', '["\\((x + 4)^2 + 6\\)","\\((x + 8)^2 - 6\\)","\\((x + 4)^2 - 6\\)","\\((x - 4)^2 - 6\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0072', 'quadratics-polynomials', 'How many real solutions does \(x^2 + 2x + 5 = 0\) have?', 'The discriminant is \(2^2 - 4(1)(5) = -16 < 0\), so there are no real solutions.', 'mc', '["\\(1\\)","\\(2\\)","infinitely many","\\(0\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0073', 'quadratics-polynomials', 'If \((x - 3)\) is a factor of \(x^2 - x - 6\), what is the other factor?', '\(x^2 - x - 6 = (x - 3)(x + 2)\), so the other factor is \(x + 2\).', 'mc', '["\\(x + 2\\)","\\(x - 2\\)","\\(x + 3\\)","\\(x - 6\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0074', 'quadratics-polynomials', 'A ball''s height is \(h(t) = -16t^2 + 32t\). At what time \(t > 0\) does it return to the ground?', 'Set \(h = 0\): \(-16t(t - 2) = 0\), so \(t = 0\) or \(t = 2\); it lands at \(t = 2\).', 'mc', '["\\(1\\)","\\(2\\)","\\(32\\)","\\(16\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0075', 'quadratics-polynomials', 'The solutions of \(x^2 + bx + 12 = 0\) are \(x = 2\) and \(x = 6\). What is \(b\)?', 'The sum of the roots is \(-b\): \(2 + 6 = 8\), so \(-b = 8\) and \(b = -8\).', 'mc', '["\\(8\\)","\\(12\\)","\\(-8\\)","\\(-12\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0076', 'quadratics-polynomials', 'Solve \(x^2 = 6x - 9\).', 'Rearrange: \(x^2 - 6x + 9 = 0\), so \((x - 3)^2 = 0\) and \(x = 3\) (a double root).', 'mc', '["\\(x = 3\\) and \\(x = -3\\)","\\(x = 9\\)","\\(x = 6\\) and \\(x = -3\\)","\\(x = 3\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('quad-0077', 'quadratics-polynomials', 'The parabola \(y = x^2 - 2x - 3\) crosses the \(x\)-axis at which two points?', 'Set \(y = 0\): \((x - 3)(x + 1) = 0\), so \(x = 3\) or \(x = -1\).', 'mc', '["\\((3, 0)\\) and \\((-1, 0)\\)","\\((-3, 0)\\) and \\((1, 0)\\)","\\((3, 0)\\) and \\((1, 0)\\)","\\((0, -3)\\) and \\((0, 1)\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0029', 'exponential-functions', 'Evaluate \(2^5\).', '\(2^5 = 2 \cdot 2 \cdot 2 \cdot 2 \cdot 2 = 32\).', 'mc', '["\\(32\\)","\\(10\\)","\\(25\\)","\\(16\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0030', 'exponential-functions', 'Evaluate \(3^4\).', '\(3^4 = 3 \cdot 3 \cdot 3 \cdot 3 = 81\).', 'mc', '["\\(12\\)","\\(81\\)","\\(64\\)","\\(27\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0031', 'exponential-functions', 'Evaluate \(5^3\).', '\(5^3 = 5 \cdot 5 \cdot 5 = 125\).', 'mc', '["\\(15\\)","\\(25\\)","\\(125\\)","\\(150\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0032', 'exponential-functions', 'If \(f(x) = 3 \cdot 2^x\), what is \(f(2)\)?', '\(f(2) = 3 \cdot 2^2 = 3 \cdot 4 = 12\).', 'mc', '["\\(6\\)","\\(36\\)","\\(18\\)","\\(12\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0033', 'exponential-functions', 'If \(f(x) = 5 \cdot 2^x\), what is the initial value \(f(0)\)?', 'Any nonzero base to the \(0\) power is \(1\), so \(f(0) = 5 \cdot 1 = 5\).', 'mc', '["\\(5\\)","\\(10\\)","\\(1\\)","\\(2\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0034', 'exponential-functions', 'In the model \(y = 100 \cdot (1.05)^x\), is this growth or decay?', 'The base \(1.05 > 1\), so the quantity grows.', 'mc', '["decay","growth","neither","linear"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0035', 'exponential-functions', 'In the model \(y = 200 \cdot (0.9)^x\), is this growth or decay?', 'The base \(0.9 < 1\), so the quantity decays.', 'mc', '["growth","neither","decay","linear"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0036', 'exponential-functions', 'A population increases by \(6\%\) each year. What is the growth factor?', 'A \(6\%\) increase multiplies by \(1 + 0.06 = 1.06\) each year.', 'mc', '["\\(0.06\\)","\\(6\\)","\\(0.94\\)","\\(1.06\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0037', 'exponential-functions', 'A quantity decreases by \(15\%\) each year. What is the decay factor?', 'A \(15\%\) decrease multiplies by \(1 - 0.15 = 0.85\) each year.', 'mc', '["\\(0.85\\)","\\(0.15\\)","\\(1.15\\)","\\(15\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0038', 'exponential-functions', 'Simplify \(x^3 \cdot x^4\).', 'When multiplying like bases, add exponents: \(x^{3+4} = x^7\).', 'mc', '["\\(x^{12}\\)","\\(x^7\\)","\\(x^1\\)","\\(2x^7\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0039', 'exponential-functions', 'Simplify \((x^2)^5\).', 'A power raised to a power multiplies exponents: \(x^{2 \cdot 5} = x^{10}\).', 'mc', '["\\(x^7\\)","\\(x^{25}\\)","\\(x^{10}\\)","\\(x^3\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0040', 'exponential-functions', 'Evaluate \(2^{-3}\).', 'A negative exponent is a reciprocal: \(2^{-3} = \tfrac{1}{2^3} = \tfrac18\).', 'mc', '["\\(-8\\)","\\(-6\\)","\\(6\\)","\\(\\tfrac18\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0041', 'exponential-functions', 'Evaluate \(7^0\).', 'Any nonzero number to the \(0\) power equals \(1\).', 'mc', '["\\(1\\)","\\(0\\)","\\(7\\)","\\(-7\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0042', 'exponential-functions', 'A bacteria colony doubles every hour, starting at \(50\). How many are there after \(3\) hours?', 'After \(3\) doublings: \(50 \cdot 2^3 = 50 \cdot 8 = 400\).', 'mc', '["\\(150\\)","\\(400\\)","\\(300\\)","\\(200\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0043', 'exponential-functions', 'If \(f(x) = 4^x\), what is \(f(3)\)?', '\(f(3) = 4^3 = 64\).', 'mc', '["\\(12\\)","\\(43\\)","\\(64\\)","\\(81\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0044', 'exponential-functions', 'Simplify \(\dfrac{x^8}{x^3}\).', 'When dividing like bases, subtract exponents: \(x^{8-3} = x^5\).', 'mc', '["\\(x^{11}\\)","\\(x^{24}\\)","\\(x^2\\)","\\(x^5\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0045', 'exponential-functions', 'Write \(0.0003\) in scientific notation.', 'Move the decimal \(4\) places right: \(0.0003 = 3 \times 10^{-4}\).', 'mc', '["\\(3 \\times 10^{-4}\\)","\\(3 \\times 10^{4}\\)","\\(3 \\times 10^{-3}\\)","\\(0.3 \\times 10^{-3}\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0046', 'exponential-functions', 'If \(f(x) = 2 \cdot 3^x\), what is \(f(1)\)?', '\(f(1) = 2 \cdot 3^1 = 6\).', 'mc', '["\\(5\\)","\\(6\\)","\\(9\\)","\\(2\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0047', 'exponential-functions', 'A savings account of \(500\) dollars grows by \(10\%\) in one year. What is the balance after one year, in dollars?', '\(500 \cdot 1.10 = 550\) dollars.', 'mc', '["\\(510\\)","\\(600\\)","\\(550\\)","\\(505\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0048', 'exponential-functions', 'Evaluate \(10^4\).', '\(10^4 = 10 \cdot 10 \cdot 10 \cdot 10 = 10{,}000\).', 'mc', '["\\(40\\)","\\(1000\\)","\\(100000\\)","\\(10000\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0049', 'exponential-functions', 'A car worth \(20{,}000\) dollars loses half its value each year. What is it worth after \(2\) years, in dollars?', 'After \(2\) halvings: \(20000 \cdot (\tfrac12)^2 = 20000 \cdot \tfrac14 = 5000\) dollars.', 'mc', '["\\(5000\\)","\\(10000\\)","\\(0\\)","\\(2500\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0050', 'exponential-functions', 'Which base makes \(y = b^x\) an increasing function?', 'For \(y = b^x\) to increase, the base must satisfy \(b > 1\); of the choices, only \(3\) qualifies.', 'mc', '["\\(0.5\\)","\\(3\\)","\\(1\\)","\\(0.1\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0051', 'exponential-functions', 'Simplify \(x^0 + x^1\) for \(x \neq 0\).', '\(x^0 = 1\) and \(x^1 = x\), so the sum is \(1 + x\).', 'mc', '["\\(x\\)","\\(2x\\)","\\(1 + x\\)","\\(0\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0052', 'exponential-functions', 'If \(f(x) = 6 \cdot (\tfrac12)^x\), what is \(f(2)\)?', '\(f(2) = 6 \cdot (\tfrac12)^2 = 6 \cdot \tfrac14 = 1.5\).', 'mc', '["\\(3\\)","\\(6\\)","\\(12\\)","\\(1.5\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0053', 'exponential-functions', 'A \(3\%\) annual growth is modeled by \(y = P(1 + r)^t\). What is \(r\)?', 'The rate as a decimal is \(r = 0.03\).', 'mc', '["\\(0.03\\)","\\(3\\)","\\(1.03\\)","\\(0.3\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0054', 'exponential-functions', 'Evaluate \(4^{1/2}\).', '\(4^{1/2} = \sqrt{4} = 2\).', 'mc', '["\\(16\\)","\\(2\\)","\\(8\\)","\\(0.5\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0055', 'exponential-functions', 'If a value triples every day starting at \(2\), what is it after \(2\) days?', '\(2 \cdot 3^2 = 2 \cdot 9 = 18\).', 'mc', '["\\(6\\)","\\(12\\)","\\(18\\)","\\(8\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0056', 'exponential-functions', 'In \(y = 8 \cdot (1.25)^x\), what is the percent growth rate per step?', 'The base \(1.25 = 1 + 0.25\), a growth rate of \(25\%\).', 'mc', '["\\(125\\%\\)","\\(8\\%\\)","\\(1.25\\%\\)","\\(25\\%\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0057', 'exponential-functions', 'An investment of \(1{,}000\) dollars earns \(8\%\) compounded annually. What is its value after \(2\) years, in dollars?', '\(1000 \cdot (1.08)^2 = 1000 \cdot 1.1664 = 1166.40\) dollars.', 'mc', '["\\(1166.4\\)","\\(1160\\)","\\(1080\\)","\\(1166\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0058', 'exponential-functions', 'A substance has a half-life of \(3\) years. If \(80\) grams remain now, how much remains after \(9\) years?', 'Nine years is \(3\) half-lives: \(80 \cdot (\tfrac12)^3 = 80 \cdot \tfrac18 = 10\) grams.', 'mc', '["\\(20\\)","\\(10\\)","\\(40\\)","\\(26.7\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0059', 'exponential-functions', 'Solve \(2^x = 32\).', 'Since \(32 = 2^5\), we have \(x = 5\).', 'mc', '["\\(16\\)","\\(6\\)","\\(5\\)","\\(4\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0060', 'exponential-functions', 'Solve \(3^{x} = 81\).', 'Since \(81 = 3^4\), we have \(x = 4\).', 'mc', '["\\(27\\)","\\(3\\)","\\(5\\)","\\(4\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0061', 'exponential-functions', 'A population of \(500\) grows \(20\%\) per year. Which function models the population after \(t\) years?', 'Growth of \(20\%\) uses a factor of \(1.2\): \(P = 500(1.2)^t\).', 'mc', '["\\(P = 500 (1.2)^t\\)","\\(P = 500 (0.2)^t\\)","\\(P = 500 + 20t\\)","\\(P = 500 (1.02)^t\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0062', 'exponential-functions', 'A car worth \(24{,}000\) dollars depreciates \(25\%\) per year. What is its value after \(2\) years, in dollars?', '\(24000 \cdot (0.75)^2 = 24000 \cdot 0.5625 = 13500\) dollars.', 'mc', '["\\(12000\\)","\\(13500\\)","\\(18000\\)","\\(6000\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0063', 'exponential-functions', 'The value of \(y = 4 \cdot 2^x\) at \(x = 5\) is what?', '\(4 \cdot 2^5 = 4 \cdot 32 = 128\).', 'mc', '["\\(40\\)","\\(1024\\)","\\(128\\)","\\(64\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0064', 'exponential-functions', 'An exponential function passes through \((0, 3)\) and \((1, 12)\). What is its base?', 'With \(f(0) = 3\) and \(f(1) = 3b = 12\), the base is \(b = 4\).', 'mc', '["\\(9\\)","\\(3\\)","\\(15\\)","\\(4\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0065', 'exponential-functions', 'Simplify \(\dfrac{2^{10}}{2^{7}}\).', 'Subtract exponents: \(2^{10-7} = 2^3 = 8\).', 'mc', '["\\(8\\)","\\(2\\)","\\(6\\)","\\(128\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0066', 'exponential-functions', 'A colony starts at \(64\) and is halved each hour. After how many hours are \(8\) left?', '\(64 \cdot (\tfrac12)^t = 8\) means \((\tfrac12)^t = \tfrac18 = (\tfrac12)^3\), so \(t = 3\).', 'mc', '["\\(8\\)","\\(3\\)","\\(4\\)","\\(2\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0067', 'exponential-functions', 'Which is equivalent to \(9^x\)?', 'Since \(9 = 3^2\), \(9^x = (3^2)^x = 3^{2x}\).', 'mc', '["\\(3^{x+2}\\)","\\(3^{x^2}\\)","\\(3^{2x}\\)","\\(6^x\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0068', 'exponential-functions', 'An account grows from \(1{,}000\) to \(1{,}210\) dollars in \(2\) years compounded annually. What is the annual rate?', '\(1000(1 + r)^2 = 1210\) gives \((1 + r)^2 = 1.21\), so \(1 + r = 1.1\) and \(r = 10\%\).', 'mc', '["\\(21\\%\\)","\\(10.5\\%\\)","\\(5\\%\\)","\\(10\\%\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0069', 'exponential-functions', 'If \(f(x) = 2^x\), by what factor does \(f\) increase when \(x\) increases by \(3\)?', '\(\dfrac{2^{x+3}}{2^x} = 2^3 = 8\).', 'mc', '["\\(8\\)","\\(3\\)","\\(6\\)","\\(2\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0070', 'exponential-functions', 'A tree''s height follows \(h = 5 (1.1)^t\) meters. What is its height at \(t = 0\), in meters?', 'At \(t = 0\), \(h = 5 (1.1)^0 = 5\) meters.', 'mc', '["\\(5.5\\)","\\(5\\)","\\(1.1\\)","\\(0\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0071', 'exponential-functions', 'Solve \(4^x = \tfrac{1}{16}\).', '\(\tfrac{1}{16} = 4^{-2}\), so \(x = -2\).', 'mc', '["\\(2\\)","\\(-4\\)","\\(-2\\)","\\(4\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0072', 'exponential-functions', 'A medicine''s concentration drops \(30\%\) each hour. What fraction remains after \(3\) hours?', '\((0.7)^3 = 0.343\) of the original remains.', 'mc', '["\\(0.1\\)","\\(0.7\\)","\\(0.9\\)","\\(0.343\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('exp-0073', 'exponential-functions', 'Which grows faster for large \(x\): \(y = 2^x\) or \(y = x^2\)?', 'Exponential growth eventually outpaces any polynomial, so \(2^x\) grows faster for large \(x\).', 'mc', '["\\(2^x\\)","\\(x^2\\)","they grow equally","neither grows"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0020', 'data-statistics', 'What is the mean of \(4, 8, 6, 2\)?', 'Mean \(= \dfrac{4 + 8 + 6 + 2}{4} = \dfrac{20}{4} = 5\).', 'mc', '["\\(5\\)","\\(20\\)","\\(6\\)","\\(4\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0021', 'data-statistics', 'What is the median of \(3, 7, 2, 9, 5\)?', 'Sorted: \(2, 3, 5, 7, 9\). The middle value is \(5\).', 'mc', '["\\(7\\)","\\(5\\)","\\(2\\)","\\(5.2\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0022', 'data-statistics', 'What is the mode of \(2, 4, 4, 6, 8\)?', 'The mode is the most frequent value, which is \(4\).', 'mc', '["\\(6\\)","\\(24\\)","\\(4\\)","\\(4.8\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0023', 'data-statistics', 'What is the range of \(10, 4, 7, 15, 6\)?', 'Range \(= \text{max} - \text{min} = 15 - 4 = 11\).', 'mc', '["\\(15\\)","\\(9\\)","\\(42\\)","\\(11\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0024', 'data-statistics', 'A bag has \(3\) red and \(7\) blue marbles. What is the probability of drawing a red marble?', 'There are \(10\) marbles, \(3\) red: \(P = \tfrac{3}{10}\).', 'mc', '["\\(\\tfrac{3}{10}\\)","\\(\\tfrac{3}{7}\\)","\\(\\tfrac{7}{10}\\)","\\(\\tfrac{1}{3}\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0025', 'data-statistics', 'What is the mean of \(12, 18, 24, 30\)?', 'Mean \(= \dfrac{84}{4} = 21\).', 'mc', '["\\(84\\)","\\(21\\)","\\(24\\)","\\(18\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0026', 'data-statistics', 'What is the median of \(6, 2, 8, 4\)?', 'Sorted: \(2, 4, 6, 8\). The median is the average of the two middle values: \(\tfrac{4 + 6}{2} = 5\).', 'mc', '["\\(4\\)","\\(6\\)","\\(5\\)","\\(20\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0027', 'data-statistics', 'A die is rolled once. What is the probability of rolling a number greater than \(4\)?', 'Favorable outcomes are \(5\) and \(6\): \(P = \tfrac{2}{6} = \tfrac13\).', 'mc', '["\\(\\tfrac16\\)","\\(\\tfrac12\\)","\\(\\tfrac23\\)","\\(\\tfrac13\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0028', 'data-statistics', 'The mean of \(5\) numbers is \(10\). What is their sum?', 'Sum \(= \text{mean} \times \text{count} = 10 \times 5 = 50\).', 'mc', '["\\(50\\)","\\(2\\)","\\(15\\)","\\(10\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0029', 'data-statistics', 'What is the mode of \(1, 2, 2, 3, 3, 3, 4\)?', 'The value \(3\) appears most often (three times).', 'mc', '["\\(2\\)","\\(3\\)","\\(4\\)","\\(1\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0030', 'data-statistics', 'A spinner has \(4\) equal sections numbered \(1\) to \(4\). What is the probability of landing on \(2\)?', 'One of four equally likely sections: \(P = \tfrac14\).', 'mc', '["\\(\\tfrac12\\)","\\(\\tfrac24\\)","\\(\\tfrac14\\)","\\(2\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0031', 'data-statistics', 'What is the range of \(20, 20, 20, 20\)?', 'All values are equal, so range \(= 20 - 20 = 0\).', 'mc', '["\\(20\\)","\\(80\\)","\\(4\\)","\\(0\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0032', 'data-statistics', 'The median of \(x, 4, 9\) (in sorted order) is \(4\). Which is a possible value of \(x\)?', 'For \(4\) to be the median of three sorted values, \(x\) must be at most \(4\); \(2\) works.', 'mc', '["\\(2\\)","\\(6\\)","\\(9\\)","\\(10\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0033', 'data-statistics', 'A survey of \(50\) people found \(20\) prefer tea. What fraction prefer tea?', '\(\tfrac{20}{50} = \tfrac{2}{5}\).', 'mc', '["\\(\\tfrac{1}{2}\\)","\\(\\tfrac{2}{5}\\)","\\(\\tfrac{20}{100}\\)","\\(\\tfrac{5}{2}\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0034', 'data-statistics', 'What is the mean of \(0, 5, 10\)?', 'Mean \(= \dfrac{0 + 5 + 10}{3} = 5\).', 'mc', '["\\(15\\)","\\(7.5\\)","\\(5\\)","\\(0\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0035', 'data-statistics', 'A coin is flipped twice. What is the probability of two heads?', 'Each flip is \(\tfrac12\); together \(\tfrac12 \times \tfrac12 = \tfrac14\).', 'mc', '["\\(\\tfrac12\\)","\\(\\tfrac13\\)","\\(1\\)","\\(\\tfrac14\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0036', 'data-statistics', 'What is the median of \(11, 13, 15, 17, 19, 21\)?', 'With six values, the median is the average of the third and fourth: \(\tfrac{15 + 17}{2} = 16\).', 'mc', '["\\(16\\)","\\(15\\)","\\(17\\)","\\(16.5\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0037', 'data-statistics', 'A data set is \(2, 3, 3, 4, 100\). Which measure is most affected by the \(100\)?', 'The mean uses every value, so a large outlier pulls it upward; the median and mode barely change.', 'mc', '["the median","the mean","the mode","the count"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0038', 'data-statistics', 'In a class of \(25\) students, \(15\) are girls. What percent are boys?', 'Boys \(= 10\); \(\tfrac{10}{25} = 40\%\).', 'mc', '["\\(60\\%\\)","\\(10\\%\\)","\\(40\\%\\)","\\(15\\%\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0039', 'data-statistics', 'What is the sum needed for \(6\) numbers to have a mean of \(7\)?', 'Sum \(= 7 \times 6 = 42\).', 'mc', '["\\(13\\)","\\(7\\)","\\(6\\)","\\(42\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0040', 'data-statistics', 'A jar has \(5\) green, \(3\) yellow, and \(2\) red candies. What is the probability of NOT drawing red?', 'Non-red \(= 8\) of \(10\): \(P = \tfrac{8}{10} = \tfrac45\).', 'mc', '["\\(\\tfrac{4}{5}\\)","\\(\\tfrac{1}{5}\\)","\\(\\tfrac{2}{10}\\)","\\(\\tfrac{3}{5}\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0041', 'data-statistics', 'What is the mode of \(7, 8, 9, 10\)?', 'No value repeats, so the data set has no mode.', 'mc', '["\\(7\\)","no mode","\\(8.5\\)","\\(10\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0042', 'data-statistics', 'The mean of \(3\) test scores is \(80\). Two scores are \(70\) and \(90\). What is the third?', 'The sum is \(240\); the third score is \(240 - 70 - 90 = 80\).', 'mc', '["\\(160\\)","\\(75\\)","\\(80\\)","\\(85\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0043', 'data-statistics', 'What is the range of the data \(-3, 0, 4, 9\)?', 'Range \(= 9 - (-3) = 12\).', 'mc', '["\\(9\\)","\\(6\\)","\\(3\\)","\\(12\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0044', 'data-statistics', 'A bag has tiles numbered \(1\) through \(8\). What is the probability of drawing an even number?', 'Even tiles are \(2, 4, 6, 8\): \(\tfrac{4}{8} = \tfrac12\).', 'mc', '["\\(\\tfrac12\\)","\\(\\tfrac14\\)","\\(\\tfrac18\\)","\\(\\tfrac{4}{7}\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0045', 'data-statistics', 'What is the median of \(100, 1, 2, 3, 4\)?', 'Sorted: \(1, 2, 3, 4, 100\). The middle value is \(3\).', 'mc', '["\\(22\\)","\\(3\\)","\\(2\\)","\\(4\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0046', 'data-statistics', 'The mean of \(4\) numbers is \(12\). After a fifth number is added, the mean becomes \(15\). What is the fifth number?', 'The first four sum to \(48\). Five numbers averaging \(15\) sum to \(75\), so the fifth is \(75 - 48 = 27\).', 'mc', '["\\(27\\)","\\(15\\)","\\(3\\)","\\(48\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0047', 'data-statistics', 'A student''s grade is \(60\%\) homework and \(40\%\) exam. With homework \(90\) and exam \(70\), what is the grade?', 'Weighted mean \(= 0.6(90) + 0.4(70) = 54 + 28 = 82\).', 'mc', '["\\(80\\)","\\(82\\)","\\(78\\)","\\(160\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0048', 'data-statistics', 'What value of \(x\) makes the mean of \(5, 9, x, 11\) equal to \(10\)?', 'The sum must be \(40\): \(5 + 9 + 11 = 25\), so \(x = 15\).', 'mc', '["\\(10\\)","\\(25\\)","\\(15\\)","\\(8.3\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0049', 'data-statistics', 'Class A (\(20\) students) averaged \(80\); class B (\(30\) students) averaged \(90\). What is the combined mean?', 'Combined \(= \dfrac{20(80) + 30(90)}{50} = \dfrac{1600 + 2700}{50} = \dfrac{4300}{50} = 86\).', 'mc', '["\\(85\\)","\\(170\\)","\\(84\\)","\\(86\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0050', 'data-statistics', 'Two dice are rolled. What is the probability the sum is \(7\)?', 'There are \(6\) ways to roll a \(7\) out of \(36\): \(\tfrac{6}{36} = \tfrac16\).', 'mc', '["\\(\\tfrac16\\)","\\(\\tfrac{1}{12}\\)","\\(\\tfrac{7}{36}\\)","\\(\\tfrac{1}{7}\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0051', 'data-statistics', 'The median of \(3, 7, x, 12\) (already sorted) is \(9\). What is \(x\)?', 'The median of four sorted values is \(\tfrac{7 + x}{2} = 9\), so \(x = 11\).', 'mc', '["\\(9\\)","\\(11\\)","\\(8\\)","\\(10\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0052', 'data-statistics', 'A data set has mean \(50\). If every value is increased by \(5\), what is the new mean?', 'Adding a constant to every value shifts the mean by that constant: \(50 + 5 = 55\).', 'mc', '["\\(50\\)","\\(250\\)","\\(55\\)","\\(45\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0053', 'data-statistics', 'The mean of \(6\) numbers is \(20\). If one number, \(10\), is removed, what is the mean of the remaining five?', 'Total is \(120\); removing \(10\) leaves \(110\) over \(5\) numbers: \(22\).', 'mc', '["\\(20\\)","\\(18\\)","\\(24\\)","\\(22\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0054', 'data-statistics', 'A jar has \(4\) red and \(6\) blue marbles. Two are drawn without replacement. What is the probability both are red?', '\(\tfrac{4}{10} \times \tfrac{3}{9} = \tfrac{12}{90} = \tfrac{2}{15}\).', 'mc', '["\\(\\tfrac{2}{15}\\)","\\(\\tfrac{4}{25}\\)","\\(\\tfrac{1}{6}\\)","\\(\\tfrac{2}{5}\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0055', 'data-statistics', 'Which data set has the greater standard deviation: A = \(\{10, 10, 10\}\) or B = \(\{5, 10, 15\}\)?', 'Set A has no spread (standard deviation \(0\)); set B is spread out, so B has the greater standard deviation.', 'mc', '["A","B","they are equal","cannot be determined"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0056', 'data-statistics', 'A test has mean \(75\) and a student scored \(75\). Adding this score to the data, how does the mean change?', 'Adding a value equal to the mean does not change the mean.', 'mc', '["it increases","it decreases","it stays the same","it doubles"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0057', 'data-statistics', 'In a two-way table, \(30\) of \(120\) people are adults who chose tea. What fraction of all people are adult tea-drinkers?', '\(\tfrac{30}{120} = \tfrac14\).', 'mc', '["\\(\\tfrac13\\)","\\(\\tfrac{30}{90}\\)","\\(\\tfrac{1}{30}\\)","\\(\\tfrac14\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0058', 'data-statistics', 'A spinner is split \(50\%\) red, \(30\%\) blue, \(20\%\) green. What is the probability of red or green?', 'Red or green \(= 50\% + 20\% = 70\%\).', 'mc', '["\\(70\\%\\)","\\(30\\%\\)","\\(10\\%\\)","\\(50\\%\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0059', 'data-statistics', 'The mean of \(8\) numbers is \(9\). What is the mean if a \(9\)th number equal to \(9\) is added?', 'The new value equals the current mean, so the mean stays \(9\).', 'mc', '["\\(9.5\\)","\\(9\\)","\\(8\\)","\\(18\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0060', 'data-statistics', 'A data set is \(2, 4, 6, 8, 10\). What is the mean absolute deviation from the mean?', 'The mean is \(6\); deviations are \(4, 2, 0, 2, 4\), averaging \(\tfrac{12}{5} = 2.4\).', 'mc', '["\\(6\\)","\\(2\\)","\\(2.4\\)","\\(4\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0061', 'data-statistics', 'Of \(200\) surveyed, \(60\%\) own a pet and \(25\%\) of pet owners have a dog. How many surveyed have a dog?', 'Pet owners \(= 0.6 \times 200 = 120\); dog owners \(= 0.25 \times 120 = 30\).', 'mc', '["\\(50\\)","\\(120\\)","\\(85\\)","\\(30\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0062', 'data-statistics', 'A number line dot plot shows values \(1, 1, 2, 3, 3, 3, 5\). What is the median?', 'With \(7\) values, the median is the fourth: sorted they are \(1, 1, 2, 3, 3, 3, 5\), so \(3\).', 'mc', '["\\(3\\)","\\(2\\)","\\(2.6\\)","\\(5\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0063', 'data-statistics', 'A student has scores \(82, 88, 91\) on three tests. What score on a fourth test gives a mean of \(90\)?', 'Four tests averaging \(90\) sum to \(360\). The first three sum to \(261\), so the fourth must be \(99\).', 'mc', '["\\(99\\)","\\(90\\)","\\(87\\)","\\(100\\)"]'::jsonb, 0, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0064', 'data-statistics', 'The mean of \(10\) numbers is \(15\). Removing two numbers whose mean is \(20\) gives a new mean of what?', 'Total is \(150\); the two removed sum to \(40\), leaving \(110\) over \(8\) numbers: \(\tfrac{110}{8} = 13.75\).', 'mc', '["\\(15\\)","\\(13.75\\)","\\(10\\)","\\(12.5\\)"]'::jsonb, 1, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0065', 'data-statistics', 'A class of \(20\) students has a mean score of \(75\). A new student scores \(96\), raising the class mean. What is the new mean?', 'Original total \(= 20 \times 75 = 1500\). With the new score: \(\tfrac{1500 + 96}{21} = \tfrac{1596}{21} = 76\).', 'mc', '["\\(75\\)","\\(85.5\\)","\\(76\\)","\\(80\\)"]'::jsonb, 2, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0066', 'data-statistics', 'Two dice are rolled. What is the probability that the sum is greater than \(9\)?', 'Sums greater than \(9\) are \(10\) (3 ways), \(11\) (2 ways), \(12\) (1 way) = \(6\) of \(36\): \(\tfrac16\).', 'mc', '["\\(\\tfrac{1}{9}\\)","\\(\\tfrac{5}{36}\\)","\\(\\tfrac14\\)","\\(\\tfrac16\\)"]'::jsonb, 3, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0067', 'data-statistics', 'A set of \(5\) distinct integers has median \(10\) and mean \(12\). What is the sum of the two largest values if the two smallest are \(6\) and \(8\)?', 'The sum of all five is \(5 \times 12 = 60\). Subtract the median \(10\) and the two smallest \(6 + 8 = 14\): \(60 - 10 - 14 = 36\).', 'mc', '["\\(36\\)","\\(30\\)","\\(26\\)","\\(40\\)"]'::jsonb, 0, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0068', 'data-statistics', 'In a group, \(70\%\) passed math and \(60\%\) passed science; \(50\%\) passed both. What percent passed at least one subject?', 'By inclusion-exclusion: \(70\% + 60\% - 50\% = 80\%\).', 'mc', '["\\(130\\%\\)","\\(80\\%\\)","\\(50\\%\\)","\\(90\\%\\)"]'::jsonb, 1, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0069', 'data-statistics', 'The mean weight of \(4\) boxes is \(25\) kg. A fifth box is added and the mean rises to \(28\) kg. How heavy is the fifth box, in kg?', 'Four boxes total \(100\) kg. Five boxes at \(28\) total \(140\) kg, so the fifth is \(40\) kg.', 'mc', '["\\(28\\)","\\(31\\)","\\(40\\)","\\(52\\)"]'::jsonb, 2, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('stat-0070', 'data-statistics', 'A jar has \(3\) red, \(4\) green, and \(5\) blue marbles. One is drawn and not replaced, then a second is drawn. What is the probability both are blue?', '\(\tfrac{5}{12} \times \tfrac{4}{11} = \tfrac{20}{132} = \tfrac{5}{33}\).', 'mc', '["\\(\\tfrac{25}{144}\\)","\\(\\tfrac{5}{12}\\)","\\(\\tfrac{1}{3}\\)","\\(\\tfrac{5}{33}\\)"]'::jsonb, 3, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('geo-0053', 'geometry-trigonometry', 'A rectangle has length \(8\) and width \(3\). What is its area?', 'Area \(= l \times w = 8 \times 3 = 24\).', 'mc', '["\\(24\\)","\\(22\\)","\\(11\\)","\\(48\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('geo-0054', 'geometry-trigonometry', 'A rectangle has length \(8\) and width \(3\). What is its perimeter?', 'Perimeter \(= 2(l + w) = 2(8 + 3) = 22\).', 'mc', '["\\(24\\)","\\(22\\)","\\(11\\)","\\(16\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('geo-0055', 'geometry-trigonometry', 'A triangle has base \(10\) and height \(6\). What is its area?', 'Area \(= \tfrac12 b h = \tfrac12 (10)(6) = 30\).', 'mc', '["\\(60\\)","\\(16\\)","\\(30\\)","\\(32\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('geo-0056', 'geometry-trigonometry', 'A circle has radius \(5\). What is its area, in terms of \(\pi\)?', 'Area \(= \pi r^2 = \pi (5)^2 = 25\pi\).', 'mc', '["\\(10\\pi\\)","\\(5\\pi\\)","\\(50\\pi\\)","\\(25\\pi\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('geo-0057', 'geometry-trigonometry', 'A circle has radius \(7\). What is its circumference, in terms of \(\pi\)?', 'Circumference \(= 2\pi r = 14\pi\).', 'mc', '["\\(14\\pi\\)","\\(7\\pi\\)","\\(49\\pi\\)","\\(28\\pi\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('geo-0058', 'geometry-trigonometry', 'In a right triangle, the legs are \(3\) and \(4\). What is the hypotenuse?', 'By the Pythagorean theorem, \(\sqrt{3^2 + 4^2} = \sqrt{25} = 5\).', 'mc', '["\\(7\\)","\\(5\\)","\\(12\\)","\\(25\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('geo-0059', 'geometry-trigonometry', 'Two angles of a triangle are \(50^\circ\) and \(60^\circ\). What is the third angle?', 'Angles sum to \(180^\circ\): \(180 - 50 - 60 = 70^\circ\).', 'mc', '["\\(110^\\circ\\)","\\(80^\\circ\\)","\\(70^\\circ\\)","\\(90^\\circ\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('geo-0060', 'geometry-trigonometry', 'A square has area \(36\). What is the length of one side?', 'Side \(= \sqrt{36} = 6\).', 'mc', '["\\(9\\)","\\(18\\)","\\(72\\)","\\(6\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('geo-0061', 'geometry-trigonometry', 'What is the volume of a rectangular box with dimensions \(2 \times 3 \times 4\)?', 'Volume \(= 2 \times 3 \times 4 = 24\).', 'mc', '["\\(24\\)","\\(9\\)","\\(26\\)","\\(12\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('geo-0062', 'geometry-trigonometry', 'An angle measures \(35^\circ\). What is the measure of its complement?', 'Complementary angles sum to \(90^\circ\): \(90 - 35 = 55^\circ\).', 'mc', '["\\(145^\\circ\\)","\\(55^\\circ\\)","\\(65^\\circ\\)","\\(35^\\circ\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('geo-0063', 'geometry-trigonometry', 'An angle measures \(120^\circ\). What is the measure of its supplement?', 'Supplementary angles sum to \(180^\circ\): \(180 - 120 = 60^\circ\).', 'mc', '["\\(30^\\circ\\)","\\(240^\\circ\\)","\\(60^\\circ\\)","\\(120^\\circ\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('geo-0064', 'geometry-trigonometry', 'A right triangle has legs \(6\) and \(8\). What is its area?', 'Area \(= \tfrac12 (6)(8) = 24\).', 'mc', '["\\(48\\)","\\(14\\)","\\(10\\)","\\(24\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('geo-0065', 'geometry-trigonometry', 'In an isosceles triangle, the two base angles are each \(70^\circ\). What is the vertex angle?', '\(180 - 70 - 70 = 40^\circ\).', 'mc', '["\\(40^\\circ\\)","\\(70^\\circ\\)","\\(110^\\circ\\)","\\(20^\\circ\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('geo-0066', 'geometry-trigonometry', 'A circle has diameter \(12\). What is its radius?', 'The radius is half the diameter: \(12 \div 2 = 6\).', 'mc', '["\\(24\\)","\\(6\\)","\\(12\\)","\\(3\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('geo-0067', 'geometry-trigonometry', 'What is the perimeter of an equilateral triangle with side length \(9\)?', 'All three sides are equal: \(3 \times 9 = 27\).', 'mc', '["\\(18\\)","\\(81\\)","\\(27\\)","\\(36\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('geo-0068', 'geometry-trigonometry', 'A cube has edge length \(3\). What is its volume?', 'Volume \(= 3^3 = 27\).', 'mc', '["\\(9\\)","\\(18\\)","\\(54\\)","\\(27\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('geo-0069', 'geometry-trigonometry', 'The point \((3, 4)\) is how far from the origin?', 'Distance \(= \sqrt{3^2 + 4^2} = \sqrt{25} = 5\).', 'mc', '["\\(5\\)","\\(7\\)","\\(12\\)","\\(25\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('geo-0070', 'geometry-trigonometry', 'A rectangle has area \(48\) and width \(6\). What is its length?', 'Length \(= \text{area} \div \text{width} = 48 \div 6 = 8\).', 'mc', '["\\(42\\)","\\(8\\)","\\(288\\)","\\(12\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('geo-0071', 'geometry-trigonometry', 'In a right triangle, \(\sin\theta = \tfrac{\text{opposite}}{\text{hypotenuse}}\). If the opposite side is \(3\) and the hypotenuse is \(5\), what is \(\sin\theta\)?', '\(\sin\theta = \tfrac{\text{opposite}}{\text{hypotenuse}} = \tfrac35\).', 'mc', '["\\(\\tfrac45\\)","\\(\\tfrac34\\)","\\(\\tfrac35\\)","\\(\\tfrac53\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('geo-0072', 'geometry-trigonometry', 'A parallelogram has base \(12\) and height \(5\). What is its area?', 'Area \(= b h = 12 \times 5 = 60\).', 'mc', '["\\(34\\)","\\(17\\)","\\(30\\)","\\(60\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('geo-0073', 'geometry-trigonometry', 'How many degrees are in the interior angles of a triangle, in total?', 'The interior angles of any triangle sum to \(180^\circ\).', 'mc', '["\\(180^\\circ\\)","\\(360^\\circ\\)","\\(90^\\circ\\)","\\(270^\\circ\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('geo-0074', 'geometry-trigonometry', 'A circle has area \(9\pi\). What is its radius?', 'From \(\pi r^2 = 9\pi\), \(r^2 = 9\), so \(r = 3\).', 'mc', '["\\(9\\)","\\(3\\)","\\(4.5\\)","\\(81\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('geo-0075', 'geometry-trigonometry', 'The midpoint of the segment from \((0, 0)\) to \((8, 6)\) is which point?', 'Midpoint \(= \left(\tfrac{0 + 8}{2}, \tfrac{0 + 6}{2}\right) = (4, 3)\).', 'mc', '["\\((8, 6)\\)","\\((4, 6)\\)","\\((4, 3)\\)","\\((2, 3)\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('geo-0076', 'geometry-trigonometry', 'A cylinder has radius \(2\) and height \(5\). What is its volume, in terms of \(\pi\)?', 'Volume \(= \pi r^2 h = \pi (2)^2 (5) = 20\pi\).', 'mc', '["\\(10\\pi\\)","\\(40\\pi\\)","\\(20\\)","\\(20\\pi\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('geo-0077', 'geometry-trigonometry', 'Two parallel lines are cut by a transversal. One pair of corresponding angles measures \((2x)^\circ\) and \(70^\circ\). What is \(x\)?', 'Corresponding angles are equal: \(2x = 70\), so \(x = 35\).', 'mc', '["\\(35\\)","\\(70\\)","\\(20\\)","\\(110\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('geo-0078', 'geometry-trigonometry', 'In right triangle \(ABC\), the right angle is at \(B\), \(AB = 5\), and \(BC = 12\). What is \(AC\)?', '\(AC = \sqrt{5^2 + 12^2} = \sqrt{169} = 13\).', 'mc', '["\\(13\\)","\\(17\\)","\\(7\\)","\\(\\sqrt{119}\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('geo-0079', 'geometry-trigonometry', 'A circle has circumference \(16\pi\). What is its area, in terms of \(\pi\)?', 'From \(2\pi r = 16\pi\), \(r = 8\); area \(= \pi (8)^2 = 64\pi\).', 'mc', '["\\(16\\pi\\)","\\(64\\pi\\)","\\(256\\pi\\)","\\(32\\pi\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('geo-0080', 'geometry-trigonometry', 'A rectangle''s length is twice its width, and its area is \(72\). What is its width?', 'With \(l = 2w\): \(2w^2 = 72\), so \(w^2 = 36\) and \(w = 6\).', 'mc', '["\\(12\\)","\\(36\\)","\\(6\\)","\\(8.5\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('geo-0081', 'geometry-trigonometry', 'In a \(30\text{-}60\text{-}90\) triangle, the side opposite \(30^\circ\) is \(4\). What is the hypotenuse?', 'In a \(30\text{-}60\text{-}90\) triangle, the hypotenuse is twice the side opposite \(30^\circ\): \(2 \times 4 = 8\).', 'mc', '["\\(4\\)","\\(4\\sqrt{3}\\)","\\(12\\)","\\(8\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('geo-0082', 'geometry-trigonometry', 'The circle \((x - 2)^2 + (y + 3)^2 = 25\) has what radius?', 'The equation \((x - h)^2 + (y - k)^2 = r^2\) has \(r^2 = 25\), so \(r = 5\).', 'mc', '["\\(5\\)","\\(25\\)","\\(10\\)","\\(\\sqrt{5}\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('geo-0083', 'geometry-trigonometry', 'A right triangle has a leg of \(9\) and hypotenuse \(15\). What is the other leg?', '\(\sqrt{15^2 - 9^2} = \sqrt{225 - 81} = \sqrt{144} = 12\).', 'mc', '["\\(6\\)","\\(12\\)","\\(\\sqrt{306}\\)","\\(18\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion'),
  ('geo-0084', 'geometry-trigonometry', 'The volume of a cube is \(64\). What is its surface area?', 'The edge is \(\sqrt[3]{64} = 4\); surface area \(= 6 \times 4^2 = 96\).', 'mc', '["\\(64\\)","\\(16\\)","\\(96\\)","\\(24\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'Adaptive bank expansion');
